//! ⚡ CONCURRENCY PERFORMANCE BENCHMARKS ⚡
//!
//! Professional benchmarking of concurrent data structures and patterns.
//! These benchmarks demonstrate the superior performance of lock-free
//! and wait-free data structures compared to traditional mutex-based approaches.
//!
//! ## Concurrency Patterns Covered:
//! - Lock-free counters vs Mutex counters
//! - Concurrent data structure access patterns
//! - Thread contention and scalability
//! - Channel communication patterns
//! - Async vs sync performance under load
//! - Memory ordering and atomic operations

use criterion::{black_box, criterion_group, criterion_main, BenchmarkId, Criterion, Throughput};
use songbird_core::performance::zero_cost_optimizations::{LockFreeCounter, SafeBufferPool};
use std::collections::HashMap;
use std::sync::{
    atomic::{AtomicU64, Ordering},
    Arc, Mutex, RwLock,
};
use std::thread;
use std::time::{Duration, Instant};
use tokio::runtime::Runtime;
use tokio::sync::{mpsc, Semaphore};

// ===== LOCK-FREE vs MUTEX COUNTER BENCHMARKS =====

fn bench_counter_performance(c: &mut Criterion) {
    let mut group = c.benchmark_group("Counter Performance");
    group.throughput(Throughput::Elements(100000));

    // Single-threaded baseline
    group.bench_function("Raw u64 (single-thread)", |b| {
        b.iter(|| {
            let mut counter = 0u64;
            for _ in 0..100000 {
                counter += 1;
                black_box(counter);
            }
        })
    });

    group.bench_function("LockFreeCounter (single-thread)", |b| {
        b.iter(|| {
            let counter = LockFreeCounter::new();
            for _ in 0..100000 {
                black_box(counter.increment());
            }
        })
    });

    group.bench_function("Mutex<u64> (single-thread)", |b| {
        b.iter(|| {
            let counter = Mutex::new(0u64);
            for _ in 0..100000 {
                let mut guard = counter.lock().map_err(|e| {
                    SongbirdError::runtime_error(&format!("Lock acquisition failed: {}", e))
                })?;
                *guard += 1;
                black_box(*guard);
            }
        })
    });

    group.bench_function("AtomicU64 (single-thread)", |b| {
        b.iter(|| {
            let counter = AtomicU64::new(0);
            for _ in 0..100000 {
                black_box(counter.fetch_add(1, Ordering::SeqCst));
            }
        })
    });

    // Multi-threaded scaling tests
    for num_threads in [2, 4, 8, 16].iter() {
        let ops_per_thread = 100000 / num_threads;

        // Lock-free counter scaling
        group.bench_with_input(
            BenchmarkId::new("LockFreeCounter", num_threads),
            num_threads,
            |b, &num_threads| {
                b.iter(|| {
                    let counter = Arc::new(LockFreeCounter::new());
                    let handles: Vec<_> = (0..num_threads)
                        .map(|_| {
                            let counter = counter.clone();
                            thread::spawn(move || {
                                for _ in 0..ops_per_thread {
                                    black_box(counter.increment());
                                }
                            })
                        })
                        .collect();

                    for handle in handles {
                        handle.join().map_err(|e| {
                            SongbirdError::runtime_error(&format!("Thread join failed: {:?}", e))
                        })?;
                    }

                    black_box(counter.get());
                })
            },
        );

        // Mutex counter scaling
        group.bench_with_input(
            BenchmarkId::new("Mutex<u64>", num_threads),
            num_threads,
            |b, &num_threads| {
                b.iter(|| {
                    let counter = Arc::new(Mutex::new(0u64));
                    let handles: Vec<_> = (0..num_threads)
                        .map(|_| {
                            let counter = counter.clone();
                            thread::spawn(move || {
                                for _ in 0..ops_per_thread {
                                    let mut guard = counter.lock().map_err(|e| {
                                        SongbirdError::runtime_error(&format!(
                                            "Lock acquisition failed: {}",
                                            e
                                        ))
                                    })?;
                                    *guard += 1;
                                    black_box(*guard);
                                }
                            })
                        })
                        .collect();

                    for handle in handles {
                        handle.join().map_err(|e| {
                            SongbirdError::runtime_error(&format!("Thread join failed: {:?}", e))
                        })?;
                    }

                    let final_value = *counter.lock().map_err(|e| {
                        SongbirdError::runtime_error(&format!("Lock acquisition failed: {}", e))
                    })?;
                    black_box(final_value);
                })
            },
        );

        // AtomicU64 scaling (baseline)
        group.bench_with_input(
            BenchmarkId::new("AtomicU64", num_threads),
            num_threads,
            |b, &num_threads| {
                b.iter(|| {
                    let counter = Arc::new(AtomicU64::new(0));
                    let handles: Vec<_> = (0..num_threads)
                        .map(|_| {
                            let counter = counter.clone();
                            thread::spawn(move || {
                                for _ in 0..ops_per_thread {
                                    black_box(counter.fetch_add(1, Ordering::SeqCst));
                                }
                            })
                        })
                        .collect();

                    for handle in handles {
                        handle.join().map_err(|e| {
                            SongbirdError::runtime_error(&format!("Thread join failed: {:?}", e))
                        })?;
                    }

                    black_box(counter.load(Ordering::SeqCst));
                })
            },
        );
    }

    group.finish();
}

// ===== CONCURRENT DATA STRUCTURE ACCESS BENCHMARKS =====

fn bench_concurrent_data_structures(c: &mut Criterion) {
    let mut group = c.benchmark_group("Concurrent Data Structures");

    const NUM_OPERATIONS: usize = 10000;

    // Concurrent HashMap access patterns
    for num_threads in [2, 4, 8].iter() {
        // Read-heavy workload (90% reads, 10% writes)
        group.bench_with_input(
            BenchmarkId::new("HashMap RwLock (read-heavy)", num_threads),
            num_threads,
            |b, &num_threads| {
                let map = Arc::new(RwLock::new(HashMap::new()));

                // Pre-populate the map
                {
                    let mut map_guard = map.write().expect("Test operation should succeed");
                    for i in 0..1000 {
                        map_guard.insert(i, format!("value_{}", i));
                    }
                }

                b.iter(|| {
                    let handles: Vec<_> = (0..num_threads)
                        .map(|thread_id| {
                            let map = map.clone();
                            thread::spawn(move || {
                                for i in 0..NUM_OPERATIONS {
                                    if i % 10 == 0 {
                                        // 10% writes
                                        let mut guard =
                                            map.write().expect("Test operation should succeed");
                                        guard.insert(
                                            thread_id * NUM_OPERATIONS + i,
                                            format!("new_value_{}", i),
                                        );
                                        black_box(());
                                    } else {
                                        // 90% reads
                                        let guard =
                                            map.read().expect("Test operation should succeed");
                                        let result = guard.get(&(i % 1000));
                                        black_box(result);
                                    }
                                }
                            })
                        })
                        .collect();

                    for handle in handles {
                        handle.join().map_err(|e| {
                            SongbirdError::runtime_error(&format!("Thread join failed: {:?}", e))
                        })?;
                    }
                })
            },
        );

        // Write-heavy workload (30% reads, 70% writes)
        group.bench_with_input(
            BenchmarkId::new("HashMap RwLock (write-heavy)", num_threads),
            num_threads,
            |b, &num_threads| {
                let map = Arc::new(RwLock::new(HashMap::new()));

                b.iter(|| {
                    let handles: Vec<_> = (0..num_threads)
                        .map(|thread_id| {
                            let map = map.clone();
                            thread::spawn(move || {
                                for i in 0..NUM_OPERATIONS {
                                    if i % 10 < 3 {
                                        // 30% reads
                                        let guard =
                                            map.read().expect("Test operation should succeed");
                                        let result = guard.get(&(i % 100));
                                        black_box(result);
                                    } else {
                                        // 70% writes
                                        let mut guard =
                                            map.write().expect("Test operation should succeed");
                                        guard.insert(
                                            thread_id * NUM_OPERATIONS + i,
                                            format!("value_{}", i),
                                        );
                                        black_box(());
                                    }
                                }
                            })
                        })
                        .collect();

                    for handle in handles {
                        handle.join().map_err(|e| {
                            SongbirdError::runtime_error(&format!("Thread join failed: {:?}", e))
                        })?;
                    }
                })
            },
        );

        // Mutex-based HashMap (comparison)
        group.bench_with_input(
            BenchmarkId::new("HashMap Mutex", num_threads),
            num_threads,
            |b, &num_threads| {
                let map = Arc::new(Mutex::new(HashMap::new()));

                b.iter(|| {
                    let handles: Vec<_> = (0..num_threads)
                        .map(|thread_id| {
                            let map = map.clone();
                            thread::spawn(move || {
                                for i in 0..NUM_OPERATIONS {
                                    let mut guard = map.lock().map_err(|e| {
                                        SongbirdError::runtime_error(&format!(
                                            "Lock acquisition failed: {}",
                                            e
                                        ))
                                    })?;
                                    if i % 10 == 0 {
                                        let result = guard.get(&(i % 100));
                                        black_box(result);
                                    } else {
                                        guard.insert(
                                            thread_id * NUM_OPERATIONS + i,
                                            format!("value_{}", i),
                                        );
                                    }
                                }
                            })
                        })
                        .collect();

                    for handle in handles {
                        handle.join().map_err(|e| {
                            SongbirdError::runtime_error(&format!("Thread join failed: {:?}", e))
                        })?;
                    }
                })
            },
        );
    }

    group.finish();
}

// ===== BUFFER POOL CONCURRENCY BENCHMARKS =====

fn bench_concurrent_buffer_pools(c: &mut Criterion) {
    let mut group = c.benchmark_group("Concurrent Buffer Pools");
    group.throughput(Throughput::Elements(1000));

    for num_threads in [2, 4, 8].iter() {
        // Our safe buffer pool
        group.bench_with_input(
            BenchmarkId::new("SafeBufferPool", num_threads),
            num_threads,
            |b, &num_threads| {
                let pool = Arc::new(SafeBufferPool::new());

                // Warmup the pool
                for _ in 0..20 {
                    pool.get_buffer(4096);
                }

                b.iter(|| {
                    let handles: Vec<_> = (0..num_threads)
                        .map(|_| {
                            let pool = pool.clone();
                            thread::spawn(move || {
                                for _ in 0..(1000 / num_threads) {
                                    let buffer = pool.get_buffer(4096);
                                    // Simulate some work with the buffer
                                    black_box(&buffer);
                                }
                            })
                        })
                        .collect();

                    for handle in handles {
                        handle.join().map_err(|e| {
                            SongbirdError::runtime_error(&format!("Thread join failed: {:?}", e))
                        })?;
                    }
                })
            },
        );

        // Direct allocation baseline
        group.bench_with_input(
            BenchmarkId::new("Direct Vec allocation", num_threads),
            num_threads,
            |b, &num_threads| {
                b.iter(|| {
                    let handles: Vec<_> = (0..num_threads)
                        .map(|_| {
                            thread::spawn(move || {
                                for _ in 0..(1000 / num_threads) {
                                    let buffer: Vec<u8> = Vec::with_capacity(4096);
                                    black_box(&buffer);
                                }
                            })
                        })
                        .collect();

                    for handle in handles {
                        handle.join().map_err(|e| {
                            SongbirdError::runtime_error(&format!("Thread join failed: {:?}", e))
                        })?;
                    }
                })
            },
        );
    }

    group.finish();
}

// ===== CHANNEL COMMUNICATION BENCHMARKS =====

fn bench_channel_communication(c: &mut Criterion) {
    let mut group = c.benchmark_group("Channel Communication");
    group.throughput(Throughput::Elements(10000));

    // Standard library channels
    group.bench_function("std::sync::mpsc", |b| {
        b.iter(|| {
            let (tx, rx) = std::sync::mpsc::channel();

            let sender = thread::spawn(move || {
                for i in 0..10000 {
                    tx.send(i).expect("Test operation should succeed");
                }
            });

            let receiver = thread::spawn(move || {
                for _ in 0..10000 {
                    let value = rx.recv().expect("Test operation should succeed");
                    black_box(value);
                }
            });

            sender.join().map_err(|e| {
                SongbirdError::runtime_error(&format!("Thread join failed: {:?}", e))
            })?;
            receiver.join().map_err(|e| {
                SongbirdError::runtime_error(&format!("Thread join failed: {:?}", e))
            })?;
        })
    });

    // Tokio channels (async)
    let rt = Runtime::new().expect("Test operation should succeed");
    group.bench_function("tokio::sync::mpsc", |b| {
        b.to_async(&rt).iter(|| async {
            let (tx, mut rx) = mpsc::channel(1000);

            let sender = tokio::spawn(async move {
                for i in 0..10000 {
                    tx.send(i).await.expect("Test operation should succeed");
                }
            });

            let receiver = tokio::spawn(async move {
                for _ in 0..10000 {
                    let value = rx.recv().await.expect("Test operation should succeed");
                    black_box(value);
                }
            });

            let _ = tokio::join!(sender, receiver);
        })
    });

    // Multiple producer, single consumer
    group.bench_function("MPSC (4 producers)", |b| {
        b.iter(|| {
            let (tx, rx) = std::sync::mpsc::channel();

            let producers: Vec<_> = (0..4)
                .map(|producer_id| {
                    let tx = tx.clone();
                    thread::spawn(move || {
                        for i in 0..2500 {
                            tx.send(producer_id * 2500 + i)
                                .expect("Test operation should succeed");
                        }
                    })
                })
                .collect();

            drop(tx); // Close the channel when all producers are done

            let consumer = thread::spawn(move || {
                let mut count = 0;
                while let Ok(value) = rx.recv() {
                    black_box(value);
                    count += 1;
                }
                count
            });

            for producer in producers {
                producer.join().map_err(|e| {
                    SongbirdError::runtime_error(&format!("Thread join failed: {:?}", e))
                })?;
            }

            let received = consumer.join().map_err(|e| {
                SongbirdError::runtime_error(&format!("Thread join failed: {:?}", e))
            })?;
            black_box(received);
        })
    });

    group.finish();
}

// ===== ASYNC vs SYNC PERFORMANCE BENCHMARKS =====

fn bench_async_vs_sync(c: &mut Criterion) {
    let mut group = c.benchmark_group("Async vs Sync Performance");

    let rt = Runtime::new().expect("Test operation should succeed");

    // CPU-bound task comparison
    group.bench_function("Sync CPU-bound task", |b| {
        b.iter(|| {
            let handles: Vec<_> = (0..8)
                .map(|_| {
                    thread::spawn(|| {
                        let mut sum = 0u64;
                        for i in 0..10000 {
                            sum = sum.wrapping_add(i).wrapping_mul(17);
                        }
                        black_box(sum);
                    })
                })
                .collect();

            for handle in handles {
                handle.join().map_err(|e| {
                    SongbirdError::runtime_error(&format!("Thread join failed: {:?}", e))
                })?;
            }
        })
    });

    group.bench_function("Async CPU-bound task", |b| {
        b.to_async(&rt).iter(|| async {
            let tasks: Vec<_> = (0..8)
                .map(|_| {
                    tokio::task::spawn_blocking(|| {
                        let mut sum = 0u64;
                        for i in 0..10000 {
                            sum = sum.wrapping_add(i).wrapping_mul(17);
                        }
                        black_box(sum);
                    })
                })
                .collect();

            for task in tasks {
                task.await.expect("Test operation should succeed");
            }
        })
    });

    // I/O simulation with delays
    group.bench_function("Sync I/O simulation", |b| {
        b.iter(|| {
            let handles: Vec<_> = (0..100)
                .map(|_| {
                    thread::spawn(|| {
                        thread::sleep(Duration::from_millis(1));
                        black_box(42);
                    })
                })
                .collect();

            for handle in handles {
                handle.join().map_err(|e| {
                    SongbirdError::runtime_error(&format!("Thread join failed: {:?}", e))
                })?;
            }
        })
    });

    group.bench_function("Async I/O simulation", |b| {
        b.to_async(&rt).iter(|| async {
            let tasks: Vec<_> = (0..100)
                .map(|_| {
                    tokio::spawn(async {
                        tokio::time::sleep(Duration::from_millis(1)).await;
                        black_box(42);
                    })
                })
                .collect();

            for task in tasks {
                task.await.expect("Test operation should succeed");
            }
        })
    });

    group.finish();
}

// ===== SEMAPHORE AND RATE LIMITING BENCHMARKS =====

fn bench_semaphores_and_rate_limiting(c: &mut Criterion) {
    let mut group = c.benchmark_group("Semaphores and Rate Limiting");

    let rt = Runtime::new().expect("Test operation should succeed");

    // Semaphore-controlled access
    for permits in [1, 4, 8, 16].iter() {
        group.bench_with_input(
            BenchmarkId::new("Tokio Semaphore", permits),
            permits,
            |b, &permits| {
                b.to_async(&rt).iter(|| async {
                    let semaphore = Arc::new(Semaphore::new(permits));

                    let tasks: Vec<_> = (0..100)
                        .map(|_| {
                            let semaphore = semaphore.clone();
                            tokio::spawn(async move {
                                let _permit = semaphore
                                    .acquire()
                                    .await
                                    .expect("Test operation should succeed");
                                // Simulate some work
                                tokio::time::sleep(Duration::from_micros(100)).await;
                                black_box(42);
                            })
                        })
                        .collect();

                    for task in tasks {
                        task.await.expect("Test operation should succeed");
                    }
                })
            },
        );
    }

    group.finish();
}

// ===== MEMORY ORDERING PERFORMANCE BENCHMARKS =====

fn bench_memory_ordering(c: &mut Criterion) {
    let mut group = c.benchmark_group("Memory Ordering Performance");
    group.throughput(Throughput::Elements(100000));

    let atomic = Arc::new(AtomicU64::new(0));

    // Different memory orderings
    for ordering in [
        ("Relaxed", Ordering::Relaxed),
        ("Acquire", Ordering::Acquire),
        ("Release", Ordering::Release),
        ("AcqRel", Ordering::AcqRel),
        ("SeqCst", Ordering::SeqCst),
    ]
    .iter()
    {
        group.bench_function(ordering.0, |b| {
            let atomic = atomic.clone();
            b.iter(|| {
                for _ in 0..100000 {
                    black_box(atomic.fetch_add(1, ordering.1));
                }
                atomic.store(0, ordering.1); // Reset for next iteration
            })
        });
    }

    // Concurrent memory ordering comparison
    for ordering in [
        ("Relaxed (concurrent)", Ordering::Relaxed),
        ("SeqCst (concurrent)", Ordering::SeqCst),
    ]
    .iter()
    {
        group.bench_function(ordering.0, |b| {
            b.iter(|| {
                let atomic = Arc::new(AtomicU64::new(0));
                let handles: Vec<_> = (0..4)
                    .map(|_| {
                        let atomic = atomic.clone();
                        thread::spawn(move || {
                            for _ in 0..25000 {
                                black_box(atomic.fetch_add(1, ordering.1));
                            }
                        })
                    })
                    .collect();

                for handle in handles {
                    handle.join().map_err(|e| {
                        SongbirdError::runtime_error(&format!("Thread join failed: {:?}", e))
                    })?;
                }

                black_box(atomic.load(ordering.1));
            })
        });
    }

    group.finish();
}

criterion_group!(
    benches,
    bench_counter_performance,
    bench_concurrent_data_structures,
    bench_concurrent_buffer_pools,
    bench_channel_communication,
    bench_async_vs_sync,
    bench_semaphores_and_rate_limiting,
    bench_memory_ordering
);

criterion_main!(benches);

//! 🧠 MEMORY PATTERNS PERFORMANCE BENCHMARKS 🧠
//!
//! Professional benchmarking of memory allocation patterns and memory-efficient
//! data structures. These benchmarks demonstrate our zero-allocation patterns
//! and memory reuse strategies.
//!
//! ## Memory Patterns Covered:
//! - Stack vs heap allocation patterns
//! - Memory pool efficiency and reuse
//! - Cache-friendly data structure layouts
//! - Memory fragmentation avoidance
//! - Large data structure memory usage
//! - RAII and automatic memory management efficiency

use criterion::{black_box, criterion_group, criterion_main, BenchmarkId, Criterion, Throughput};
use songbird_core::performance::zero_cost_optimizations::{FixedCircularBuffer, SafeBufferPool};
use std::alloc::{GlobalAlloc, Layout, System};
use std::collections::{BTreeMap, HashMap, VecDeque};
use std::mem;
use std::sync::Arc;
use std::thread;
use std::time::{Duration, Instant};

// ===== STACK VS HEAP ALLOCATION BENCHMARKS =====

fn bench_stack_vs_heap_allocation(c: &mut Criterion) {
    let mut group = c.benchmark_group("Stack vs Heap Allocation");
    group.throughput(Throughput::Elements(10000));

    // Stack allocation (array on stack)
    group.bench_function("Stack Array[1024]", |b| {
        b.iter(|| {
            for _ in 0..10000 {
                let arr: [u32; 1024] = [0; 1024];
                black_box(arr);
            }
        })
    });

    // Heap allocation (Vec)
    group.bench_function("Heap Vec<u32>(1024)", |b| {
        b.iter(|| {
            for _ in 0..10000 {
                let vec: Vec<u32> = vec![0; 1024];
                black_box(vec);
            }
        })
    });

    // Heap allocation with capacity (no reallocation)
    group.bench_function("Heap Vec::with_capacity(1024)", |b| {
        b.iter(|| {
            for _ in 0..10000 {
                let mut vec: Vec<u32> = Vec::with_capacity(1024);
                vec.resize(1024, 0);
                black_box(vec);
            }
        })
    });

    // Box allocation (single heap allocation)
    group.bench_function("Box<[u32; 1024]>", |b| {
        b.iter(|| {
            for _ in 0..10000 {
                let boxed = Box::new([0u32; 1024]);
                black_box(boxed);
            }
        })
    });

    group.finish();
}

// ===== BUFFER POOL VS DIRECT ALLOCATION BENCHMARKS =====

fn bench_buffer_pools(c: &mut Criterion) {
    let mut group = c.benchmark_group("Buffer Pool vs Direct Allocation");
    group.throughput(Throughput::Elements(1000));

    // Different buffer sizes
    for size in [1024, 4096, 16384, 65536].iter() {
        // Our buffer pool (memory reuse)
        group.bench_with_input(
            BenchmarkId::new("SafeBufferPool", size),
            size,
            |b, &size| {
                let mut pool = SafeBufferPool::new();

                // Warmup the pool
                for _ in 0..10 {
                    let _ = pool.get_buffer(size);
                }

                b.iter(|| {
                    for _ in 0..1000 {
                        let buffer = pool.get_buffer(size);
                        black_box(&buffer);
                    }
                })
            },
        );

        // Direct Vec allocation (new allocation each time)
        group.bench_with_input(
            BenchmarkId::new("Direct Vec::with_capacity", size),
            size,
            |b, &size| {
                b.iter(|| {
                    for _ in 0..1000 {
                        let buffer: Vec<u8> = Vec::with_capacity(size);
                        black_box(&buffer);
                    }
                })
            },
        );

        // Pre-zeroed allocation
        group.bench_with_input(
            BenchmarkId::new("Zeroed vec![0u8; size]", size),
            size,
            |b, &size| {
                b.iter(|| {
                    for _ in 0..1000 {
                        let buffer = vec![0u8; size];
                        black_box(&buffer);
                    }
                })
            },
        );
    }

    group.finish();
}

// ===== MEMORY LAYOUT AND CACHE EFFICIENCY BENCHMARKS =====

fn bench_memory_layout_efficiency(c: &mut Criterion) {
    let mut group = c.benchmark_group("Memory Layout Efficiency");

    const SIZE: usize = 1024 * 1024; // 1MB of data

    // Array of Structures (AoS) - cache unfriendly for some operations
    #[derive(Clone, Copy)]
    struct Point3D {
        x: f32,
        y: f32,
        z: f32,
    }

    // Structure of Arrays (SoA) - cache friendly for vectorized operations
    struct Points3D {
        x: Vec<f32>,
        y: Vec<f32>,
        z: Vec<f32>,
    }

    let aos_data: Vec<Point3D> = (0..SIZE)
        .map(|i| Point3D {
            x: i as f32,
            y: (i * 2) as f32,
            z: (i * 3) as f32,
        })
        .collect();

    let soa_data = Points3D {
        x: (0..SIZE).map(|i| i as f32).collect(),
        y: (0..SIZE).map(|i| (i * 2) as f32).collect(),
        z: (0..SIZE).map(|i| (i * 3) as f32).collect(),
    };

    // Benchmark accessing X coordinates only (cache efficiency test)
    group.bench_function("AoS - Access X only", |b| {
        b.iter(|| {
            let mut sum = 0.0f32;
            for point in &aos_data {
                sum += point.x;
            }
            black_box(sum);
        })
    });

    group.bench_function("SoA - Access X only", |b| {
        b.iter(|| {
            let mut sum = 0.0f32;
            for &x in &soa_data.x {
                sum += x;
            }
            black_box(sum);
        })
    });

    // Benchmark accessing all coordinates (different access pattern)
    group.bench_function("AoS - Access All", |b| {
        b.iter(|| {
            let mut sum = 0.0f32;
            for point in &aos_data {
                sum += point.x + point.y + point.z;
            }
            black_box(sum);
        })
    });

    group.bench_function("SoA - Access All", |b| {
        b.iter(|| {
            let mut sum = 0.0f32;
            for i in 0..soa_data.x.len() {
                sum += soa_data.x[i] + soa_data.y[i] + soa_data.z[i];
            }
            black_box(sum);
        })
    });

    group.finish();
}

// ===== CIRCULAR BUFFER MEMORY EFFICIENCY BENCHMARKS =====

fn bench_circular_buffer_memory(c: &mut Criterion) {
    let mut group = c.benchmark_group("Circular Buffer Memory Efficiency");
    group.throughput(Throughput::Elements(100000));

    const BUFFER_SIZE: usize = 1024;
    let test_data: Vec<u64> = (0..100000).collect();

    // Our fixed circular buffer (no allocations after init)
    group.bench_function("FixedCircularBuffer (zero-alloc)", |b| {
        b.iter(|| {
            let mut buffer = FixedCircularBuffer::<u64, BUFFER_SIZE>::new();
            for &item in &test_data {
                buffer.push(item);
            }
            black_box(&buffer);
        })
    });

    // VecDeque with pre-allocation
    group.bench_function("VecDeque (pre-allocated)", |b| {
        b.iter(|| {
            let mut buffer = VecDeque::with_capacity(BUFFER_SIZE);
            for &item in &test_data {
                if buffer.len() == BUFFER_SIZE {
                    buffer.pop_front();
                }
                buffer.push_back(item);
            }
            black_box(&buffer);
        })
    });

    // VecDeque without pre-allocation (many allocations)
    group.bench_function("VecDeque (dynamic alloc)", |b| {
        b.iter(|| {
            let mut buffer = VecDeque::new();
            for &item in &test_data {
                if buffer.len() == BUFFER_SIZE {
                    buffer.pop_front();
                }
                buffer.push_back(item);
            }
            black_box(&buffer);
        })
    });

    // Vec with circular indexing (manual circular buffer)
    group.bench_function("Vec circular indexing", |b| {
        b.iter(|| {
            let mut buffer = vec![0u64; BUFFER_SIZE];
            let mut index = 0;
            for &item in &test_data {
                buffer[index] = item;
                index = (index + 1) % BUFFER_SIZE;
            }
            black_box(&buffer);
        })
    });

    group.finish();
}

