// ===== MEMORY ACCESS PATTERN BENCHMARKS =====

fn bench_memory_patterns(c: &mut Criterion) {
    let mut group = c.benchmark_group("Memory Access Patterns");

    const SIZE: usize = 1024 * 1024; // 1MB of u32s
    let data: Vec<u32> = (0..SIZE as u32).collect();

    // Sequential access (cache-friendly)
    group.bench_function("Sequential Access", |b| {
        b.iter(|| {
            let mut sum = 0u64;
            for &value in &data {
                sum += value as u64;
            }
            black_box(sum);
        })
    });

    // Stride access patterns
    for stride in [2, 4, 8, 16, 64].iter() {
        group.bench_with_input(
            BenchmarkId::new("Stride Access", stride),
            stride,
            |b, &stride| {
                b.iter(|| {
                    let mut sum = 0u64;
                    let mut i = 0;
                    while i < data.len() {
                        sum += data[i] as u64;
                        i += stride;
                    }
                    black_box(sum);
                })
            },
        );
    }

    // Random access (cache-unfriendly, but realistic for some workloads)
    group.bench_function("Random Access", |b| {
        // Pre-compute random indices to avoid RNG overhead in benchmark
        let indices: Vec<usize> = (0..10000)
            .map(|i| (i * 17 + 42) % data.len()) // Simple pseudo-random
            .collect();

        b.iter(|| {
            let mut sum = 0u64;
            for &idx in &indices {
                sum += data[idx] as u64;
            }
            black_box(sum);
        })
    });

    group.finish();
}

// ===== ZERO-ALLOCATION PATTERNS BENCHMARK =====

fn bench_zero_allocation_patterns(c: &mut Criterion) {
    let mut group = c.benchmark_group("Zero-Allocation Patterns");
    group.throughput(Throughput::Elements(10000));

    // Configuration processing with stack allocation
    group.bench_function("Stack-allocated config processing", |b| {
        b.iter(|| {
            let mut measurement = PerformanceMeasurement::new("benchmark");
            for i in 0..10000 {
                // Simulate config processing with no heap allocation
                let config_value = i * 2 + 1;
                let processed = config_value.wrapping_mul(17).wrapping_add(42);
                black_box(processed);
            }
            black_box(measurement.ops_per_second());
        })
    });

    // String formatting (unavoidably allocates)
    group.bench_function("String formatting (allocating)", |b| {
        b.iter(|| {
            for i in 0..10000 {
                let formatted = format!("config_value_{}", i);
                black_box(formatted);
            }
        })
    });

    // Arithmetic operations only
    group.bench_function("Pure arithmetic (zero-allocation)", |b| {
        b.iter(|| {
            let mut accumulator = 0u64;
            for i in 0..10000 {
                accumulator = accumulator
                    .wrapping_add(i as u64)
                    .wrapping_mul(17)
                    .wrapping_add(42);
            }
            black_box(accumulator);
        })
    });

    group.finish();
}

// ===== REALISTIC WORKLOAD BENCHMARKS =====

fn bench_realistic_workloads(c: &mut Criterion) {
    let mut group = c.benchmark_group("Realistic Workloads");

    // Simulate a configuration update cycle
    group.bench_function("Config Update Cycle", |b| {
        let mut interner = SafeStringInterner::new();
        let mut counter = LockFreeCounter::new();
        let mut buffer = FixedCircularBuffer::<u32, 256>::new();
        let mut pool = SafeBufferPool::new();

        // Warmup
        for i in 0..100 {
            interner.intern(&format!("config_key_{}", i % 20));
            pool.get_buffer(1024);
        }

        b.iter(|| {
            // Simulate receiving 100 configuration updates
            for i in 0..100 {
                // Intern configuration keys
                let key_id = interner.intern(&format!("config_key_{}", i % 20));

                // Update metrics
                counter.increment();

                // Buffer the change
                buffer.push(i as u32);

                // Process with temporary buffer
                let temp_buffer = pool.get_buffer(512);

                black_box((key_id, counter.get(), temp_buffer.len()));
            }
        })
    });

    // Simulate a high-throughput message processing scenario
    group.bench_function("Message Processing Pipeline", |b| {
        let counter = Arc::new(LockFreeCounter::new());
        let mut buffers: Vec<FixedCircularBuffer<u64, 128>> =
            (0..4).map(|_| FixedCircularBuffer::new()).collect();

        b.iter(|| {
            // Process 1000 messages across 4 pipelines
            for i in 0..1000u64 {
                let pipeline = i % 4;

                // Route message to appropriate pipeline buffer
                buffers[pipeline as usize].push(i);

                // Update global counter
                counter.increment();

                // Simulate some processing
                let processed = i.wrapping_mul(17).wrapping_add(42);
                black_box(processed);
            }

            black_box(counter.get());
        })
    });

    group.finish();
}

criterion_group!(
    benches,
    bench_string_interning,
    bench_lock_free_counters,
    bench_circular_buffers,
    bench_buffer_pools,
    bench_memory_patterns,
    bench_zero_allocation_patterns,
    bench_realistic_workloads
);

criterion_main!(benches);

/// # Zero-Cost Service Registry Benchmark
///
/// Performance comparison between traditional HashMap-based service registries
/// and our new zero-cost compile-time service resolution patterns.

use criterion::{black_box, criterion_group, criterion_main, Criterion};
use std::collections::HashMap;
use std::sync::{Arc, RwLock};
use std::time::Duration;
use songbird_errors::SongbirdResult;

// ============================================================================
// TRADITIONAL DI PATTERN (Baseline - SLOW)
// ============================================================================

struct TraditionalServiceRegistry {
    services: Arc<RwLock<HashMap<String, Box<dyn TraditionalService + Send + Sync>>>>,
}

trait TraditionalService: Send + Sync {
    fn get_name(&self) -> &str;
    fn process(&self, data: &str) -> String;
}

struct TraditionalSecurityService;
struct TraditionalStorageService;
struct TraditionalComputeService;

impl TraditionalService for TraditionalSecurityService {
    fn get_name(&self) -> &str { "security" }
    fn process(&self, data: &str) -> String { format!("Security processed: {}", data) }
}

impl TraditionalService for TraditionalStorageService {
    fn get_name(&self) -> &str { "storage" }
    fn process(&self, data: &str) -> String { format!("Storage processed: {}", data) }
}

impl TraditionalService for TraditionalComputeService {
    fn get_name(&self) -> &str { "compute" }
    fn process(&self, data: &str) -> String { format!("Compute processed: {}", data) }
}

impl TraditionalServiceRegistry {
    fn new() -> Self {
        Self {
            services: Arc::new(RwLock::new(HashMap::new())),
        }
    }

    fn register(&self, name: &str, service: Box<dyn TraditionalService + Send + Sync>) {
        let mut services = self.services.write().unwrap_or_else(|e| {
    tracing::error!("Unwrap failed: {:?}", e);
    return Err(std::io::Error::new(
    std::io::ErrorKind::Other,
    format!("Operation failed - {}: {:?}", "unable to continue", e)
).into())
}); // Lock overhead
        services.insert(name.to_string(), service); // HashMap insertion
    }

    fn get_service(&self, name: &str) -> Option<String> {
        let services = self.services.read().unwrap_or_else(|e| {
    tracing::error!("Unwrap failed: {:?}", e);
    return Err(std::io::Error::new(
    std::io::ErrorKind::Other,
    format!("Operation failed - {}: {:?}", "unable to continue", e)
).into())
}); // Lock overhead
        if let Some(service) = services.get(name) { // HashMap lookup
            Some(service.process("test data")) // Virtual dispatch
        } else {
            None
        }
    }
}

// ============================================================================
// ZERO-COST PATTERN (Target - FAST)
// ============================================================================

struct ZeroCostServiceRegistry<Security, Storage, Compute> {
    security_service: Security,    // Direct field - zero overhead
    storage_service: Storage,      // Direct field - zero overhead
    compute_service: Compute,      // Direct field - zero overhead
}

trait ZeroCostService {
    fn get_name(&self) -> &'static str;
    fn process(&self, data: &str) -> String;
}

struct ZeroCostSecurityService;
struct ZeroCostStorageService;
struct ZeroCostComputeService;

impl ZeroCostService for ZeroCostSecurityService {
    fn get_name(&self) -> &'static str { "security" }
    fn process(&self, data: &str) -> String { format!("Zero-cost security: {}", data) }
}

impl ZeroCostService for ZeroCostStorageService {
    fn get_name(&self) -> &'static str { "storage" }
    fn process(&self, data: &str) -> String { format!("Zero-cost storage: {}", data) }
}

impl ZeroCostService for ZeroCostComputeService {
    fn get_name(&self) -> &'static str { "compute" }
    fn process(&self, data: &str) -> String { format!("Zero-cost compute: {}", data) }
}

impl<Security, Storage, Compute> ZeroCostServiceRegistry<Security, Storage, Compute>
where
    Security: ZeroCostService,
    Storage: ZeroCostService,
    Compute: ZeroCostService,
{
    fn new(security: Security, storage: Storage, compute: Compute) -> Self {
        Self {
            security_service: security,
            storage_service: storage,
            compute_service: compute,
        }
    }

    #[inline] // Compiler inlines for zero overhead
    fn security(&self) -> &Security { &self.security_service }

    #[inline] // Compiler inlines for zero overhead
    fn storage(&self) -> &Storage { &self.storage_service }

    #[inline] // Compiler inlines for zero overhead
    fn compute(&self) -> &Compute { &self.compute_service }
}

// ============================================================================
// BENCHMARKS
// ============================================================================

fn benchmark_traditional_service_registry(c: &mut Criterion) {
    let registry = TraditionalServiceRegistry::new();
    registry.register("security", Box::new(TraditionalSecurityService));
    registry.register("storage", Box::new(TraditionalStorageService));
    registry.register("compute", Box::new(TraditionalComputeService));

    c.bench_function("traditional_service_lookup", |b| {
        b.iter(|| {
            // Every lookup involves:
            // 1. RwLock read acquisition
            // 2. HashMap string key lookup 
            // 3. Virtual dispatch through trait object
            let result1 = registry.get_service(black_box("security"));
            let result2 = registry.get_service(black_box("storage")); 
            let result3 = registry.get_service(black_box("compute"));
            (result1, result2, result3)
        })
    });
}

fn benchmark_zero_cost_service_registry(c: &mut Criterion) {
    let registry = ZeroCostServiceRegistry::new(
        ZeroCostSecurityService,  // Stack allocated
        ZeroCostStorageService,   // Stack allocated
        ZeroCostComputeService,   // Stack allocated
    );

    c.bench_function("zero_cost_service_lookup", |b| {
        b.iter(|| {
            // Every lookup involves:
            // 1. Direct field access (inlined)
            // 2. No HashMap lookup
            // 3. Compile-time dispatch (monomorphized)
            let result1 = black_box(registry.security().process("test data"));
            let result2 = black_box(registry.storage().process("test data"));
            let result3 = black_box(registry.compute().process("test data"));
            (result1, result2, result3)
        })
    });
}

fn benchmark_service_creation(c: &mut Criterion) {
    c.bench_function("traditional_service_creation", |b| {
        b.iter(|| {
            let registry = TraditionalServiceRegistry::new();
            registry.register("security", Box::new(TraditionalSecurityService));
            registry.register("storage", Box::new(TraditionalStorageService));
            registry.register("compute", Box::new(TraditionalComputeService));
            black_box(registry)
        })
    });

    c.bench_function("zero_cost_service_creation", |b| {
        b.iter(|| {
            let registry = ZeroCostServiceRegistry::new(
                ZeroCostSecurityService,
                ZeroCostStorageService,
                ZeroCostComputeService,
            );
            black_box(registry)
        })
    });
}

criterion_group!(
    benches,
    benchmark_traditional_service_registry,
    benchmark_zero_cost_service_registry,
    benchmark_service_creation
);
criterion_main!(benches);

