    let max_retries = 3;

    loop {
        match simulate_recoverable_error(retry_count).await {
            Ok(_) => break,
            Err(e) if retry_count < max_retries => {
                retry_count += 1;
                tokio::time::sleep(Duration::from_millis(100)).await;
                continue;
            }
            Err(e) => return Err(e),
        }
    }

    assert!(retry_count > 0, "Should have required at least one retry");
    Ok(())
}

