#[derive(Debug)]
pub struct WorkflowResult {
    pub workflow_name: String,
    pub steps: Vec<StepResult>,
    pub total_duration: Duration,
    pub success: bool,
}

impl WorkflowResult {
    pub fn new(name: &str) -> Self {
        Self {
            workflow_name: name.to_string(),
            steps: Vec::new(),
            total_duration: Duration::default(),
            success: true,
        }
    }

    pub fn add_step(&mut self, step_name: &str, result: SongbirdResult<StepResult>) {
        match result {
            Ok(mut step) => {
                step.step_name = step_name.to_string();
                if !step.success {
                    self.success = false;
                }
                self.steps.push(step);
            }
            Err(e) => {
                let failed_step = StepResult::failure(step_name, e.to_string(), Duration::default());
                self.steps.push(failed_step);
                self.success = false;
            }
        }
    }

    pub fn success_rate(&self) -> f32 {
        let successful = self.steps.iter().filter(|s| s.success).count();
        successful as f32 / self.steps.len() as f32
    }
}

#[derive(Debug)]
pub struct StepResult {
    pub step_name: String,
    pub success: bool,
    pub message: String,
    pub error_details: Option<String>,
    pub duration: Duration,
}

impl StepResult {
    pub fn success(message: &str, duration: Duration) -> Self {
        Self {
            step_name: String::new(),
            success: true,
            message: message.to_string(),
            error_details: None,
            duration,
        }
    }

    pub fn failure(message: &str, error: String, duration: Duration) -> Self {
        Self {
            step_name: String::new(),
            success: false,
            message: message.to_string(),
            error_details: Some(error),
            duration,
        }
    }
}

