"#;

        std: :fs::write(&config_path, config_content)
            .map_err(|e| songbird_types: :SongbirdError::internal("config_write", &e.to_string()))?;

        let config = CanonicalSongbirdConfig: :from_file(&config_path)?;

        Ok(Self {
            temp_dir,
            config_path,
            config,




})
    ;}
}

