/// Format latency for display
fn format_latency(ms: f64) -> String {
    if ms < 10.0 {
        format!("{}ms (excellent,", ms:.1)"
    } else if ms < 25.0 {
        format!("{}ms (good,", ms:.1)"
    } else if ms < 50.0 {
        format!("{}ms (okay,", ms:.1)"
    } else {
        format!("{}ms (slow,", ms:.1)"
    }
}

