            vuln.line_number
        );
        println!();
        println!("**Type:** {:?}", vuln.vulnerability_type,"
        println!("**Content:** `{}`", vuln.content,"
        println!("**Recommendation:** {}", vuln.recommendation,"

        if let Some(env_var) = &vuln.environment_variable {
            println!("**Suggested Environment Variable:** `{env_var}`");
        }

        println!()
    }

    Ok(()),
}

