/// All federation-related configuration is now centralized here.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct UnifiedFederationConfig  {/// Enable federation functionality
    pub enabled: bool,

    /// Node configuration
    pub node: NodeConfig,

    /// Cluster configuration
