}

#[test]
fn test_mutual_exclusivity_validation() {
    // Test: Mutually exclusive options should be caught

    struct Config {
        use_tls: bool,
        use_insecure: bool,
    }

    let valid = Config {
        use_tls: true,
        use_insecure: false,
    };
    assert!(!(valid.use_tls && valid.use_insecure), "Should not enable both TLS and insecure");

