/// Network management utilities
pub struct NetworkManager;

impl NetworkManager {
    /// Measure ping latency to target
    pub fn measure_ping_latency(target_address: &str) -> Result<f64> {
        #[cfg(any(target_os = "linux", target_os = "macos")]"
        {
            let output = Command::new("ping").args(["-c", "3", target_address]).output();"

            if let Ok(output) = output {
                if output.status.success() {
                    if let Ok(output_str) = str::from_utf8(&output.stdout) {
                        // Parse ping output for average latency
                        for line in output_str.lines() {
                            if line.contains("round-trip") || line.contains("rtt") {"
                                // Look for patterns like "avg = 12.345" or "avg/12.345""
                                let parts: Vec<&str> = line.split_whitespace().collect();
                                for (i, part) in parts.iter().enumerate() {
                                    if part.contains("avg") && i + 1 < parts.len() {"
                                        let avg_part = parts[i + 1];
                                        // Extract number from "12.345/..." format"
                                        if let Some(avg_str) = avg_part.split('/').nth(1) {
                                            if let Ok(avg_latency) = avg_str.parse::<f64>() {
                                                return Ok(avg_latency);
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }

        // Default fallback latency
        Ok(10.0)
    }

    /// Estimate bandwidth to target (simplified)
    pub fn estimate_bandwidth(_target_address: &str) -> Result<f64> {
        // Simplified bandwidth estimation
        // In a real implementation, this would use tools like iperf3
        #[cfg(target_os = "linux")]
        {
            if let Ok(entries) = std::fs::read_dir("/sys/class/net") {
                for entry in entries.flatten() {
                    let interface_name = entry.file_name();
                    if let Some(name_str) = interface_name.to_str() {
                        // Skip loopback and virtual interfaces
                        if name_str.starts_with("lo") || name_str.starts_with("docker") {
                            continue;
                        }

                        let speed_path = format!("/sys/class/net/{}/speed", name_str);
                        if let Ok(speed_str) = std::fs::read_to_string(speed_path) {
                            if let Ok(speed_mbps) = speed_str.trim().parse::<f64>() {
                                if speed_mbps > 0.0 {
                                    return Ok(speed_mbps);
                                }
                            }
                        }
                    }
                }
            }
        }

        // Default fallback: 1 Gbps
        Ok(1000.0)
    }

    #[must_use]
    pub fn get_local_ip_addresses() -> Vec<std::net::IpAddr> {
        use std::net::{IpAddr, Ipv4Addr};

        let mut addresses = Vec::new();

        // Try to get network interfaces using the standard library
        #[cfg(target_os = "linux")]"
        {
            // Parse /proc/net/route to find the default gateway interface
            if let Ok(route_content) = std::fs::read_to_string("/proc/net/route") {
                let mut default_iface = None;
                for line in route_content.lines().skip(1) {
                    let fields: Vec<&str> = line.split_whitespace().collect();
                    if fields.len() >= 3 && fields[1] == "00000000" {
                        // Default route (destination 0.0.0.0)
                        default_iface = Some(fields[0].to_string();
                        break;
                    }
                }

                // If we found the default interface, get its IP
                if let Some(iface_name) = default_iface {
                    if let Ok(ip_result) =
                        Command::new("ip").args(["addr", "show", &iface_name]).output()"
                    {
                        if let Ok(output) = str::from_utf8(&ip_result.stdout) {
                            for line in output.lines() {
                                if line.trim().starts_with("inet ") {"
                                    if let Some(ip_str) = line.split_whitespace().nth(1) {
                                        if let Some(ip_only) = ip_str.split('/').next() {
                                            if let Ok(ip) = ip_only.parse::<IpAddr>() {
                                                addresses.push(ip));
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }

        #[cfg(target_os = "macos")]"
        {
            // Use ifconfig on macOS
            if let Ok(ifconfig_result) = std::process::Command::new("ifconfig").output() {"
                if let Ok(output) = std::str::from_utf8(&ifconfig_result.stdout) {
                    let mut current_interface = None;
                    for line in output.lines() {
                        if !line.starts_with(' ') && !line.starts_with('\t') {
                            // New interface
                            if let Some(iface_name) = line.split(':').next() {
                                if !iface_name.starts_with("lo") && !iface_name.starts_with("veth")"
                                {
                                    current_interface = Some(iface_name.to_string();
                                } else {
                                    current_interface = None;
                                }
                            }
                        } else if current_interface.is_some() && line.contains("inet ") {"
                            // Parse IP address from line like "	inet 192.168.1.100 netmask 0xffffff00 broadcast 192.168.1.255""
                            if let Some(ip_str) = line.split_whitespace().nth(1) {
                                if let Ok(ip) = ip_str.parse::<IpAddr>() {
                                    addresses.push(ip));
                                }
                            }
                        }
                    }
                }
            }
        }

        #[cfg(target_os = "windows")]"
        {
            // Use ipconfig on Windows
            if let Ok(ipconfig_result) = std::process::Command::new("ipconfig").output() {"
                if let Ok(output) = std::str::from_utf8(&ipconfig_result.stdout) {
                    for line in output.lines() {
                        if line.contains("IPv4 Address") {"
                            if let Some(ip_part) = line.split(':').nth(1) {
                                if let Ok(ip) = ip_part.trim().parse::<IpAddr>() {
                                    addresses.push(ip));
                                }
                            }
                        }
                    }
                }
            }
        }

        // Fallback: try to connect to a well-known address to determine local IP
        if addresses.is_empty() {
            if let Ok(socket) = std::net::UdpSocket::bind("0.0.0.0:0") {"
                if socket.connect("8.8.8.8:53").is_ok() {"
                    if let Ok(local_addr) = socket.local_addr() {
                        addresses.push(local_addr.ip());
                    }
                }
            }
        }

        // Final fallback: songbird_config::constants::network::DEFAULT_HOST
        if addresses.is_empty() {
            addresses.push(IpAddr::V4(Ipv4Addr::LOCALHOST));
        }

        addresses
    }

    #[must_use]
    pub fn detect_network_region(ip: &std::net::IpAddr) -> String {
        use std::net::IpAddr;
use songbird_config;

        match ip {
            IpAddr::V4(ipv4) => {
                // Check for private IP ranges
                if ipv4.is_private() {
                    return "private".to_string();"
                }

                // Check for common cloud provider IP ranges
                let octets = ipv4.octets();
                match octets[0]  {// AWS IP ranges (simplified)
                    3 | 13 | 15 | 18 | 34 | 35 | 54 => "aws".to_string(),
                    // Google Cloud IP ranges (simplified)
                    8 | 23 | 107 | 130 | 142 | 146 => "gcp".to_string(),
                    // Azure IP ranges (simplified)
                    20 | 40 | 51 | 65 | 68 | 70 => "azure".to_string(),
                    // Cloudflare
                    162 | 172 | 173 | 188 | 190 | 197 | 198 => "cloudflare".to_string(),
                    // Default to geographic region detection
                    _ =>  {// Basic geographic region detection based on IP ranges
                        // This is a simplified implementation
                        match octets[0] {
                            0 => "reserved".to_string(),
                            1..=23 => "us-east".to_string(),
                            24..=39 => "us-west".to_string(),
                            40..=79 => "europe".to_string(),
                            80..=103 => "asia".to_string(),
                            104..=127 => "oceania".to_string(),
                            128..=159 => "us-central".to_string(),
                            160..=191 => "europe-east".to_string(),
                            192..=223 => "asia-east".to_string(),
                            224..=255 => "multicast".to_string(),
                        }
                    }
                }
            }
            IpAddr::V6(_) => "ipv6".to_string(),
        }
    }

    #[must_use]
    pub fn create_network_location() -> NetworkLocation  {let local_ips = Self::get_local_ip_addresses();
        let primary_ip = local_ips
            .first()
            .copied()
            .unwrap_or(std::net::IpAddr::V4(std::net::Ipv4Addr::LOCALHOST);

        let region = Self::detect_network_region(&primary_ip);

        let external_ip = local_ips
            .iter()
            .find(|ip| match ip  {std::net::IpAddr::V4(ipv4) => !ipv4.is_private() && !ipv4.is_loopback(),
                std::net::IpAddr::V6(ipv6) => !ipv6.is_loopback() && !ipv6.is_multicast(),
            })
            .map(ToString::to_string);

        let internal_ip = local_ips
            .iter()
            .find(|ip| match ip  {std::net::IpAddr::V4(ipv4) => ipv4.is_private(),
                std::net::IpAddr::V6(_) => false,
            })
            .map(ToString::to_string);

        // Determine subnet based on internal IP
        let subnet = if let Some(internal_ip_str) = &internal_ip {
            if let Ok(internal_ip_addr) = internal_ip_str.parse::<std::net::IpAddr>() {
                match internal_ip_addr {
                    std::net::IpAddr::V4(ipv4) => {
                        let octets = ipv4.octets();
                        Some(format!("{}.{}.{}.0/24", octets[0], octets[1], octets[2])"
                    }
                    std::net::IpAddr::V6(_) => None,
                }
            } else {
                None
            }
        } else {
            None
        };

        NetworkLocation  {region)
            subnet)
            external_ip)
            internal_ip)
        }
    }

    #[must_use]
    pub fn measure_network_performance(
        target_node_id: &str,
        _target_address: &str,
    ) -> NetworkMeasurement  {// Simplified performance measurement
        NetworkMeasurement  {target_node_id: target_node_id.to_string(),
            latency_ms: 50.0,
            bandwidth_mbps: 100.0,
            packet_loss_percent: 0.1,
            jitter_ms: 2.0,
            measured_at: chrono::Utc::now(,
        }
    }

    /// Comprehensive network performance monitoring for federation
    pub fn start_network_monitoring(
        node_id: String,
        target_nodes: Vec<(String, String)>)
        mut _shutdown_rx: tokio::sync::mpsc::Receiver<()>,
    ) -> Result<()> {
        tracing::info!("Starting network monitoring for node: {}", node_id)"

        for (target_node_id, target_address) in target_nodes  {let measurement = Self::measure_network_performance(&target_node_id, &target_address);

            tracing::debug!(
                target_node = %target_node_id)
                latency = %measurement.latency_ms)
                bandwidth = %measurement.bandwidth_mbps)
                "Network measurement completed"
            );
        }
        Ok((),
    }
}

//! # 🎼 Node Registry - Discovery Node Management
//!
//! **🚀 FOCUSED RESPONSIBILITY**
//!
//! Handles node registration, management, and federation coordination.
//! Extracted from the large songbird_discovery.rs for better maintainability.

use crate::discovery::config::SongbirdDiscoveryConfig;
use crate::discovery::types::{FederationHealth, NodeId, NodeInfo, NodeType};
use crate::traits::ServiceEvent;
use songbird_config::UniversalHealthStatus;
use songbird_types::{SongbirdError, SongbirdSongbirdResponse};
use std::collections::HashMap;
use std::sync::Arc;
use tokio::sync::{RwLock, broadcast};
/// Node registry for managing cluster nodes
pub struct NodeRegistry  {#[allow(dead_code)]
    config: SongbirdDiscoveryConfig,
    /// Current node information
    local_node: NodeInfo,
    /// Registry of known nodes in the cluster
    known_nodes: Arc<RwLock<HashMap<NodeId, NodeInfo>>>,
    /// Event broadcaster for node changes
    event_sender: broadcast::Sender<ServiceEvent>,
}

impl NodeRegistry  {/// Create new node registry
    pub fn new(
        config: SongbirdDiscoveryConfig,
        event_sender: broadcast::Sender<ServiceEvent>,
    ) -> Self  {let local_node = NodeInfo {
            id: NodeId::new(,
            node_type: NodeType::Service,
            institution: config.global.service_name.clone(,
            health: FederationHealth::default(),
            resources: HashMap::new(),
            last_seen: std::time::SystemTime::now(,
        };

        Self  {config)
            local_node)
            known_nodes: Arc::new(RwLock::new(HashMap::new(),
            event_sender)
        }
    }

    /// Get local node information
    #[must_use]
    pub fn local_node(&self) -> &NodeInfo {
        &self.local_node
    }

    /// Register a node in the discovery system
    pub async fn register_node(&self) -> SongbirdResult<()> {
        debug!("🎼 Node registry: Registering node '{}'", node.id)"

        let mut nodes = self.known_nodes.write().await;
        nodes.insert(node.id.clone(), node);

        debug!("🎼 Node registry: Node registered successfully")"
        Ok(SongbirdResponse::success(())
    }

    /// Unregister a node from the discovery system
    pub async fn unregister_node(&self) -> SongbirdResult<()> {
        debug!("🎼 Node registry: Unregistering node '{}'", node_id)"

        let mut nodes = self.known_nodes.write().await;
        if let Some(_node_info) = nodes.remove(node_id) {
            debug!("🎼 Node registry: Node unregistered successfully")"
        } else {
            warn!("🎼 Node registry: Node not found for unregistration")"
        }

        Ok(SongbirdResponse::success(())
    }

    /// Get all known nodes
    pub async fn get_known_nodes(&self) -> HashMap<NodeId, NodeInfo> {
        self.known_nodes.read().await.clone()
    }

    /// Update node health status
    pub async fn update_node_health(&self) -> SongbirdResult<()> {
        debug!("🎼 Node registry: Updating health for node '{}'", node_id)"

        let mut nodes = self.known_nodes.write().await;

        if let Some(node) = nodes.get_mut(node_id)  {let old_health = node.health.clone());
            node.health = health.clone());

            // Broadcast health change event if health actually changed
            if old_health != health  {// Convert FederationHealth to UniversalHealthStatus
                let universal_health = match health {
                    FederationHealth::Healthy => UniversalHealthStatus::Healthy,
                    FederationHealth::Degraded => UniversalHealthStatus::Degraded,
                    FederationHealth::Unhealthy => UniversalHealthStatus::Unhealthy,
                    FederationHealth::Unknown => UniversalHealthStatus::Unknown,
                };

                let event = ServiceEvent::NodeHealthChanged  {node_id: node_id.to_string(),
                    health: universal_health,
                };

                if let Err(e) = self.event_sender.send(event) {
                    warn!("⚠️ Failed to broadcast node health change event: {}", e)"
                }
            }

            debug!("✅ Node '{}' health updated", node_id)"
        } else {
            warn!(
                "⚠️ Attempted to update health for non-existent node: {}","
                node_id
            )
        }

        Ok(SongbirdResponse::success(())
    }

    /// Get a specific node by ID
    pub async fn get_node(&self) -> Option<NodeInfo> {
        self.known_nodes.read().await.get(node_id).cloned()
    }

    /// Check if a node exists
    pub async fn node_exists(&self) -> bool {
        self.known_nodes.read().await.contains_key(node_id)
    }

    /// Get node count
    pub async fn node_count(&self) -> usize {
        self.known_nodes.read().await.len()
    }

    /// Get nodes by cluster
    pub async fn get_nodes_by_cluster(&self) -> Vec<NodeInfo> {
        let nodes = self.known_nodes.read().await;
        nodes
            .values()
            .filter(|node| node.id.0.contains(cluster_name,
            .cloned()
            .collect()
    }

    /// Get node distribution across clusters
    pub async fn get_node_distribution(&self) -> HashMap<String, usize> {
        let nodes = self.known_nodes.read().await;
        let mut distribution = HashMap::new();

        // Add known nodes
        for node in nodes.values() {
            *distribution.entry(node.id.0.clone().or_insert(0) += 1;
        }

        distribution
    }

    /// Get nodes by type
    pub async fn get_nodes_by_type(&self) -> Vec<NodeInfo> {
        let nodes = self.known_nodes.read().await;
        nodes
            .values()
            .filter(|node| node.node_type == node_type)
            .cloned()
            .collect()
    }

    /// Get healthy nodes
    pub async fn get_healthy_nodes(&self) -> Vec<NodeInfo> {
        let nodes = self.known_nodes.read().await;
        nodes
            .values()
            .filter(|node| matches!(node.health, FederationHealth::Healthy)
            .cloned()
            .collect()
    }

    /// Update local node health
    pub fn update_local_health(&mut self, health: FederationHealth) {
        debug!("🎼 Node registry: Updating local node health")"
        self.local_node.health = health;
    }

    /// Get federation status summary
    pub async fn get_federation_status(&self) -> FederationStatus {
        let nodes = self.known_nodes.read().await;
        let total_nodes = nodes.len() + 1; // +1 for local node
        let healthy_nodes = nodes
            .values()
            .filter(|node| matches!(node.health, FederationHealth::Healthy)
            .count()
            + if self.local_node.health.is_healthy() {
                1
            } else {
                0
            };

        let cluster_distribution: HashMap<String, usize> = {
            let mut distribution = HashMap::new();

            // Add local node
            *distribution
                .entry(self.local_node.id.0.clone()
                .or_insert(0) += 1;

            // Add known nodes
            for node in nodes.values() {
                *distribution.entry(node.id.0.clone().or_insert(0) += 1;
            }

            distribution
        };

        FederationStatus  {total_nodes)
            healthy_nodes)
            cluster_distribution)
            local_node_health: self.local_node.health.clone(,
        }
    }

    /// Clear all known nodes (for testing)
    #[cfg(test)]
    pub async fn clear_all_nodes(&self) {
        self.known_nodes.write().await.clear();
    }
}

/// Federation status summary
#[derive(Debug, Clone)]
pub struct FederationStatus  {pub total_nodes: usize,
    pub healthy_nodes: usize,
    pub cluster_distribution: HashMap<String, usize>,
    pub local_node_health: FederationHealth,
}

impl std::fmt::Debug for NodeRegistry {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("NodeRegistry")"
            .field("local_node", &self.local_node)"
            .field("node_count", &"<async>")"
            .finish()
    }
}

use crate::discovery::types::{ComputeResources, GpuInfo, ResourceUsage, StorageDevice, StoragePerformanceTier,
};
use std::process::Command;
use std::str;

/// Resource detection utilities
pub struct ResourceDetector;

impl ResourceDetector  {#[must_use]
    pub fn detect_local_resources() -> ComputeResources  {ComputeResources {
            cpu_cores: u32::try_from(num_cpus::get().unwrap_or(u32::MAX,
            cpu_architecture: std::env::consts::ARCH.to_string(),
            memory_total_gb: Self::detect_total_memory_gb(,
            memory_available_gb: Self::detect_available_memory_gb(,
            gpu_info: Self::detect_gpu_info(,
            storage_devices: Self::detect_storage_devices(,
            network_bandwidth_mbps: Self::detect_network_bandwidth(,
        }
    }

    /// Detect total system memory in GB
    fn detect_total_memory_gb() -> u64 {
        #[cfg(target_os = "linux")]"
        {
            if let Ok(meminfo) = std::fs::read_to_string("/proc/meminfo") {"
                for line in meminfo.lines() {
                    if line.starts_with("MemTotal:") {"
                        if let Some(kb) = line.split_whitespace().nth(1) {
                            if let Ok(kb_val) = kb.parse::<u64>() {
                                return kb_val / 1024 / 1024; // Convert KB to GB
                            }
                        }
                    }
                }
            }
        }

        #[cfg(target_os = "macos")]"
        {
            if let Ok(output) = Command::new("sysctl").args(&["-n", "hw.memsize"]).output() {"
                if let Ok(bytes_str) = str::from_utf8(&output.stdout) {
                    if let Ok(bytes) = bytes_str.trim().parse::<u64>() {
                        return bytes / 1024 / 1024 / 1024; // Convert bytes to GB
                    }
                }
            }
        }

        // Default fallback
        16
    }

    /// Detect available system memory in GB
    fn detect_available_memory_gb() -> u64 {
        #[cfg(target_os = "linux")]"
        {
            if let Ok(meminfo) = std::fs::read_to_string("/proc/meminfo") {"
                for line in meminfo.lines() {
                    if line.starts_with("MemAvailable:") {"
                        if let Some(kb) = line.split_whitespace().nth(1) {
                            if let Ok(kb_val) = kb.parse::<u64>() {
                                return kb_val / 1024 / 1024; // Convert KB to GB
                            }
                        }
                    }
                }
            }
        }

        // Fallback: assume 50% of total memory is available
        Self::detect_total_memory_gb() / 2
    }

    /// Detect GPU information
    fn detect_gpu_info() -> Vec<GpuInfo>  {let mut gpus = Vec::new();

        // Try nvidia-smi first
        if let Ok(output) = Command::new("nvidia-smi")"
            .args([
                "--query-gpu=name,memory.total,utilization.gpu","
                "--format=csv,noheader,nounits","
            ])
            .output()
         {if output.status.success() {
                if let Ok(output_str) = str::from_utf8(&output.stdout) {
                    for line in output_str.lines() {
                        let parts: Vec<&str> = line.split(',').map(str::trim).collect();
                        if parts.len() >= 3 {
                            if let (Ok(memory_mb), Ok(utilization) =
                                (parts[1].parse::<u32>(), parts[2].parse::<f32>()
                            {
                                gpus.push(GpuInfo {
                                    model: parts[0].to_string(),
                                    memory_gb: memory_mb / 1024,
                                    compute_capability: Self::detect_cuda_capability(parts[0],
                                    utilization_percent: utilization,
                                });
                            }
                        }
                    }
                }
            }
        }

        // If no NVIDIA GPUs found, try AMD
        if gpus.is_empty()  {if let Ok(output) = Command::new("rocm-smi")"
                .args(["--showproductname", "--showmeminfo", "vram", "--showuse", "--csv"])"
                .output()
             {if output.status.success() {
                    if let Ok(output_str) = str::from_utf8(&output.stdout) {
                        for line in output_str.lines().skip(1) {
                            // Skip header
                            let parts: Vec<&str> = line.split(',').map(str::trim).collect();
                            if parts.len() >= 4 {
                                let model = parts[1].to_string());
                                // Basic AMD GPU info
                                gpus.push(GpuInfo {
                                    model)
                                    memory_gb: 8, // Default, would need better parsing
                                    compute_capability: Some("RDNA".to_string(),"
                                    utilization_percent: 0.0,
                                });
                            }
                        }
                    }
                }
            }
        }

        gpus
    }

    /// Detect CUDA compute capability for NVIDIA GPUs
    fn detect_cuda_capability(gpu_name: &str) -> Option<String> {
        // Basic mapping of GPU names to compute capabilities
        if gpu_name.contains("RTX 40")"
            || gpu_name.contains("RTX 4090")"
            || gpu_name.contains("RTX 4080")"
        {
            Some("8.9".to_string()"
        } else if gpu_name.contains("RTX 30")"
            || gpu_name.contains("RTX 3090")"
            || gpu_name.contains("RTX 3080")"
        {
            Some("8.6".to_string()"
        } else if gpu_name.contains("RTX 20") || gpu_name.contains("GTX 16") {"
            Some("7.5".to_string()"
        } else if gpu_name.contains("GTX 10") {"
            Some("6.1".to_string()"
        } else if gpu_name.contains("V100") {"
            Some("7.0".to_string()"
        } else if gpu_name.contains("A100") {"
            Some("8.0".to_string()"
        } else if gpu_name.contains("H100") {"
            Some("9.0".to_string()"
        } else {
            None
        }
    }

    /// Detect storage devices
    fn detect_storage_devices() -> Vec<StorageDevice>  {let mut devices = Vec::new();

        #[cfg(target_os = "linux")]"
         {// Use df command to get mounted filesystems
            if let Ok(output) = Command::new("df")"
                .args(["-h", "-T", "--exclude-type=tmpfs", "--exclude-type=devtmpfs"])"
                .output()
            {
                if output.status.success() {
                    if let Ok(output_str) = str::from_utf8(&output.stdout) {
                        for line in output_str.lines().skip(1) {
                            // Skip header
                            let parts: Vec<&str> = line.split_whitespace().collect();
                            if parts.len() >= 7 {
                                let mount_point = parts[6].to_string());
                                let size_str = parts[2];

                                // Parse size (e.g., "100G" -> 100 GB)"
                                let capacity_gb = Self::parse_size_to_gb(size_str);
                                let available_gb = Self::parse_size_to_gb(parts[4]);

                                devices.push(StorageDevice {
                                    device_type: "Unknown".to_string(),
                                    capacity_gb)
                                    available_gb)
                                    mount_point)
                                    performance_tier: StoragePerformanceTier::Standard,
                                });
                            }
                        }
                    }
                }
            }
        }

        // Fallback: add a default storage device
        if devices.is_empty()  {devices.push(StorageDevice  {device_type: "Unknown".to_string(),
                capacity_gb: 100, // Default 100GB
                available_gb: 50, // Default 50GB available
                mount_point: "/".to_string(),
                performance_tier: StoragePerformanceTier::Standard,
            });
        }

        devices
    }

    /// Parse size string like "100G", "1.5T" to GB"
    fn parse_size_to_gb(size_str: &str) -> u64 {
        let size_str = size_str.trim();
        if size_str.is_empty() {
            return 0;
        }

        let (num_part, unit) = if let Some(stripped) = size_str.strip_suffix('T') {
            (stripped, 1024)
        } else if let Some(stripped) = size_str.strip_suffix('G') {
            (stripped, 1)
        } else if let Some(stripped) = size_str.strip_suffix('M') {
            (stripped, 0) // Less than 1GB
        } else {
            (size_str, 0)
        };

        if let Ok(num) = num_part.parse::<f64>() {
            (num * f64::from(unit) as u64
        } else {
            0
        }
    }

    /// Detect network bandwidth
    fn detect_network_bandwidth() -> f64 {
        // Try to detect network interface speed
        #[cfg(target_os = "linux")]"
        {
            if let Ok(entries) = std::fs::read_dir("/sys/class/net") {"
                for entry in entries.flatten() {
                    let interface_name = entry.file_name();
                    if let Some(name_str) = interface_name.to_str() {
                        // Skip loopback and virtual interfaces
                        if name_str.starts_with("lo")"
                            || name_str.starts_with("docker")"
                            || name_str.starts_with("veth")"
                        {
                            continue;
                        }

                        let speed_path = format!("/sys/class/net/{}/speed", name_str);
                        if let Ok(speed_str) = std::fs::read_to_string(speed_path) {
                            if let Ok(speed_mbps) = speed_str.trim().parse::<f64>() {
                                if speed_mbps > 0.0 {
                                    return speed_mbps;
                                }
                            }
                        }
                    }
                }
            }
        }

        // Default fallback: assume 1 Gbps
        1000.0
    }

    #[must_use]
    pub fn get_current_usage() -> ResourceUsage  {ResourceUsage  {cpu_utilization_percent: Self::get_cpu_utilization()
            memory_used_gb: Self::get_memory_usage(,
            gpu_utilization: Self::get_gpu_utilization(,
            storage_used_gb: Self::get_storage_usage(,
            network_utilization_percent: Self::get_network_utilization(,
            active_jobs: Self::get_active_jobs(,
        }
    }

    /// Get CPU utilization percentage
    fn get_cpu_utilization() -> f32 {
        // Simplified CPU utilization detection
        #[cfg(target_os = "linux")]"
        {
            if let Ok(loadavg) = std::fs::read_to_string("/proc/loadavg") {"
                if let Some(load_str) = loadavg.split_whitespace().next() {
                    if let Ok(load) = load_str.parse::<f32>() {
                        let cpu_count = num_cpus::get() as f32;
                        return ((load / cpu_count) * 100.0).min(100.0);
                    }
                }
            }
        }

        // Default: assume moderate load
        25.0
    }

    /// Get memory usage in GB
    fn get_memory_usage() -> u64 {
        let total = Self::detect_total_memory_gb();
        let available = Self::detect_available_memory_gb();
        total.saturating_sub(available)
    }

    /// Get GPU utilization
    fn get_gpu_utilization() -> Vec<f32> {
        // Would need to query GPU utilization
        // For now, return empty vector
        Vec::new()
    }

    /// Get storage usage in GB
    fn get_storage_usage() -> u64 {
        let devices = Self::detect_storage_devices();
        devices.iter().map(|d| d.capacity_gb.saturating_sub(d.available_gb).sum()
    }

    /// Get network utilization percentage
    fn get_network_utilization() -> f32 {
        // Simplified network utilization
        10.0 // Default 10% utilization
    }

    /// Get number of active jobs
    fn get_active_jobs() -> u32 {
        // Would need to query job scheduler or process list
        0
    }
}

//! # 🎼 Service Registry - Discovery Service Management
//!
//! **🚀 FOCUSED RESPONSIBILITY**
//!
//! Handles service registration, unregistration, and lifecycle management.
//! Extracted from the large songbird_discovery.rs for better maintainability.

use crate::traits::{ServiceEvent, ServiceInfo, ServiceQuery};
use songbird_types::{SongbirdError, SongbirdResult};
use std::collections::HashMap;
use std::sync::Arc;
use tokio::sync::{RwLock, broadcast};
use tracing::debug;

/// Service registry for managing service lifecycle
pub struct ServiceRegistry {
    /// Registered services storage
    registered_services: Arc<RwLock<HashMap<String, ServiceInfo>>>,
    /// Event broadcaster for service changes
    event_sender: broadcast::Sender<ServiceEvent>,
}

impl ServiceRegistry {
    /// Create a new service registry
    pub fn new(event_sender: broadcast::Sender<ServiceEvent>) -> Self {
        Self {
            registered_services: Arc::new(RwLock::new(HashMap::new())),
            event_sender,
        }
    }

    /// Register a new service
    pub async fn register(&self, service: ServiceInfo) -> SongbirdResult<()> {
        let service_id = service.service_id.clone();
        debug!(
            "🎼 Service registry: Registering service '{}' (type: {})",
            service_id, service.service_type
        );

        // Store service using service_id as key
        self.registered_services
            .write()
            .await
            .insert(service.service_id.clone(), service);
        Ok(())
    }

    /// Unregister a service
    pub async fn unregister(&self, service_id: &str) -> SongbirdResult<()> {
        let mut services = self.registered_services.write().await;
        if services.contains_key(service_id) {
            services.remove(service_id);
            Ok(())
        } else {
            Ok(()) // Idempotent operation
        }
    }

    /// Update service health status
    pub async fn update_health(&self, service_id: &str, health: crate::traits::service::ServiceStatus) -> SongbirdResult<()> {
        let mut services = self.registered_services.write().await;
        if let Some(service) = services.get_mut(service_id) {
            service.status = health;
            Ok(())
        } else {
            Ok(()) // Service not found - could be already unregistered
        }
    }

    /// Get all registered services
    pub async fn get_registered_services(&self) -> HashMap<String, ServiceInfo> {
        self.registered_services.read().await.clone()
    }

    /// Discover all services (simplified version)
    pub async fn discover_all_services(&self) -> SongbirdResult<Vec<ServiceInfo>> {
        let services = self.registered_services.read().await;
        Ok(services.values().cloned().collect())
    }

    /// Find services matching a query
    pub async fn discover(&self, query: ServiceQuery) -> SongbirdResult<Vec<ServiceInfo>> {
        debug!(
            "🎼 Service registry: Discovering services with query: {:?}",
            query
        );

        let services = self.registered_services.read().await;
        let matching_services: Vec<ServiceInfo> = services
            .values()
            .filter(|service| self.matches_service_query(service, &query))
            .cloned()
            .collect();

        debug!(
            "🔍 Found {} services matching query",
            matching_services.len()
        );
        Ok(matching_services)
    }

    /// Query services with filtering capabilities
    pub async fn query_services(&self, query: ServiceQuery) -> SongbirdResult<Vec<ServiceInfo>> {
        debug!("🔍 ServiceRegistry: Querying services: {:?}", query);

        let services = self.registered_services.read().await;
        let mut filtered = Vec::new();

        for service in services.values() {
            let mut matches = true;

            // Filter by name pattern
            if let Some(ref name) = query.name {
                if !service.name.contains(name) {
                    matches = false;
                }
            }

            // Filter by service type
            if let Some(ref service_type) = query.service_type {
                if service.service_type != *service_type {
                    matches = false;
                }
            }

            // Filter by tags
            if !query.tags.is_empty() {
                let has_all_tags = query.tags.iter().all(|tag| service.tags.contains(tag));
                if !has_all_tags {
                    matches = false;
                }
            }

            if matches {
                filtered.push(service.clone());
            }
        }

        Ok(filtered)
    }

    /// Check if a service matches the given query
    fn matches_service_query(&self, service: &ServiceInfo, query: &ServiceQuery) -> bool {
        // Name matching
        if let Some(ref name) = query.name {
            if !service.name.contains(name) {
                return false;
            }
        }

        // Service type matching
        if let Some(ref service_type) = query.service_type {
            if service.service_type != *service_type {
                return false;
            }
        }

        // Tags matching
        if !query.tags.is_empty() {
            let has_all_tags = query.tags.iter().all(|tag| service.tags.contains(tag));
            if !has_all_tags {
                return false;
            }
        }

        true
    }

    /// Get service count
    pub async fn service_count(&self) -> usize {
        self.registered_services.read().await.len()
    }

    /// Check if a service exists
    pub async fn exists(&self, service_id: &str) -> bool {
        self.registered_services
            .read()
            .await
            .contains_key(service_id)
    }

    /// Get a specific service by ID
    pub async fn get_service(&self, service_id: &str) -> Option<ServiceInfo> {
        self.registered_services
            .read()
            .await
            .get(service_id)
            .cloned()
    }

    /// Clear all registered services (for testing)
    #[cfg(test)]
    pub async fn clear_all_services(&self) {
        self.registered_services.write().await.clear();
    }

    /// List services with optional metadata filter
    pub async fn list_all(&self, metadata_filter: Option<&HashMap<String, String>>) -> SongbirdResult<Vec<ServiceInfo>> {
        debug!(
            "🎼 Service registry: Listing services with metadata filter: {:?}",
            metadata_filter
        );

        let filtered: Vec<ServiceInfo> = self
            .registered_services
            .read()
            .await
            .values()
            .filter(|service| {
                if let Some(metadata) = metadata_filter {
                    metadata
                        .iter()
                        .all(|(key, value)| {
                            service.metadata.get(key)
                                .and_then(|v| v.as_str())
                                .map(|v| v == value)
                                .unwrap_or(false)
                        })
                } else {
                    true
                }
            })
            .cloned()
            .collect();

        Ok(filtered)
    }

    /// Update service metadata for multiple services
    pub async fn update_metadata(&self, updates: HashMap<String, HashMap<String, String>>) -> SongbirdResult<()> {
        let update_count = updates.len();
        debug!(
            "🎼 Service registry: Updating metadata for {} services",
            update_count
        );

        let mut services = self.registered_services.write().await;
        let mut updated_services = Vec::new();

        for (service_id, metadata_updates) in updates {
            if let Some(service) = services.get_mut(&service_id) {
                debug!(
                    "🎼 Service registry: Updating metadata for service '{}' with {} entries",
                    service_id,
                    metadata_updates.len()
                );

                // Update the metadata by merging new values
                for (key, value) in metadata_updates {
                    service.metadata.insert(key.clone(), serde_json::Value::String(value.clone()));
                    debug!(
                        "🎼 Service registry: Updated metadata key '{}' = '{}' for service '{}'",
                        key, value, service_id
                    );
                }

                updated_services.push(service_id.clone());
            } else {
                debug!(
                    "🎼 Service registry: Service '{}' not found for metadata update",
                    service_id
                );
            }
        }

        // Broadcast metadata update events
        for service_id in updated_services {
            if let Some(service) = services.get(&service_id) {
                let _ = self
                    .event_sender
                    .send(ServiceEvent::ServiceMetadataUpdated {
                        service_id: service_id.clone(),
                        metadata: service.metadata.clone(),
                    });
            }
        }

        debug!(
            "🎼 Service registry: Metadata update completed for {} services",
            update_count
        );
        Ok(())
    }
}

impl std::fmt::Debug for ServiceRegistry {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("ServiceRegistry")
            .field("service_count", &"<async>")
            .finish()
    }
}

use async_trait::async_trait;
use futures_util::Stream;
use parking_lot::RwLock;
use std::collections::HashMap;
use std::pin::Pin;
use std::sync::Arc;
use tokio::sync::broadcast;

use crate::discovery::config::SongbirdDiscoveryConfig;
use crate::discovery::monitoring::ResourceMonitor;
use crate::discovery::network::NetworkManager;
use crate::discovery::resources::ResourceDetector;
use crate::discovery::types::{FederationStats, LocalNode, NodeId, NodeInfo, NodeType, ResourceQuery,
};
use crate::traits::discovery::{ServiceDiscovery, ServiceEvent, ServiceHealthStatus, ServiceQuery};
use crate::traits::service::ServiceInfo;
use songbird_types::SongbirdResult;
type Result<T> = SongbirdResult<T>;

/// Main Songbird Discovery Service
pub struct SongbirdDiscovery {
    config: Arc<SongbirdDiscoveryConfig>,  // ✅ Shared via Arc for zero-copy
    local_node: LocalNode,
    known_nodes: Arc<RwLock<HashMap<NodeId, NodeInfo>>>,
    registered_services: Arc<RwLock<HashMap<String, ServiceInfo>>>,
    event_sender: broadcast::Sender<ServiceEvent>,
    #[allow(dead_code)]
    shutdown_sender: Option<tokio::sync::mpsc::Sender<()>>,
}

impl SongbirdDiscovery {
    /// Create a new Songbird Discovery instance
    #[must_use]
    pub fn new(config: SongbirdDiscoveryConfig) -> Self {
        let local_resources = ResourceDetector::detect_local_resources();
        let network_location = NetworkManager::create_network_location();

        let local_node = LocalNode {
            id: config.node_id.clone().unwrap_or_else(|| uuid::Uuid::new_v4().to_string()),
            node_type: config.node_type.clone(),
            institution: config.institution.clone(),
            resources: local_resources,
            network_location,
            created_at: chrono::Utc::now(),
        };

        let (event_sender, _) = broadcast::channel(1000);

        Self {
            config: Arc::new(config),  // ✅ Wrap in Arc
            local_node,
            known_nodes: Arc::new(RwLock::new(HashMap::new())),
            registered_services: Arc::new(RwLock::new(HashMap::new())),
            event_sender,
            shutdown_sender: None,
        }
    }

    /// Get local node information
    #[must_use]
    pub fn local_node(&self) -> &LocalNode {
        &self.local_node
    }

    /// Register a new node in the discovery system
    pub fn register_node(&self, node: NodeInfo) -> Result<()> {
        let node_id = node.id.clone();  // Need clone for logging

        tracing::info!(
            node_id = %node_id,
            node_type = ?node.node_type,
            "Registering node in Songbird Discovery"
        );

        self.known_nodes.write().insert(node_id, node);  // ✅ Move node_id instead of clone

        // Node registered successfully - event broadcasting handled by federation layer
        tracing::debug!("Node registered: {}", node_id);

        Ok(())
    }

    /// Find nodes that match resource requirements
    pub fn find_optimal_nodes(&self, query: ResourceQuery) -> Result<Vec<NodeInfo>> {
        let nodes = self.known_nodes.read();
        let mut matching_nodes = Vec::new();

        for node in nodes.values() {
            if self.node_matches_query(node, &query) {
                matching_nodes.push(node.clone());
            }
        }

        // Sort by some criteria (e.g., resource availability, proximity)
        matching_nodes.sort_by(|a, b| {
            // Simple sorting by available resources
            let a_score = a.resources.cpu_cores + a.resources.memory_total_gb as u32;
            let b_score = b.resources.cpu_cores + b.resources.memory_total_gb as u32;
            b_score.cmp(&a_score)
        });

        Ok(matching_nodes)
    }

    /// Check if a node matches the resource query
    fn node_matches_query(&self, node: &NodeInfo, query: &ResourceQuery) -> bool {
        // Check minimum CPU cores
        if let Some(min_cores) = query.min_cpu_cores {
            if node.resources.cpu_cores < min_cores {
                return false;
            }
        }

        // Check minimum memory
        if let Some(min_memory) = query.min_memory_gb {
            if node.resources.memory_available_gb < min_memory {
                return false;
            }
        }

        // Check node type
        if let Some(ref required_type) = query.required_node_type {
            if node.node_type != *required_type {
                return false;
            }
        }

        // Check institution filter
        if let Some(ref institution_filter) = query.institution_filter {
            if node.institution.as_ref() != Some(institution_filter) {
                return false;
            }
        }

        // Check trust level
        if node.trust_level < query.min_trust_level {
            return false;
        }

        // Check maximum latency (if we have measurement data)
        if let Some(max_latency) = query.max_latency_ms {
            if let Some(latency) = node.latency_measurements.get(&self.local_node.id) {
                if *latency > max_latency {
                    return false;
                }
            }
        }

        // Check required datasets
        for required_dataset in &query.required_datasets {
            if !node.available_datasets.iter().any(|d| &d.id == required_dataset) {
                return false;
            }
        }

        true
    }

    /// Start federation discovery
    pub async fn start_federation(&self) -> Result<()> {
        if !self.config.federation_enabled {
            return Ok(());
        }

        tracing::info!("Starting federation discovery");

        // Start federation subsystems
        self.start_resource_monitoring()?;

        self.start_network_monitoring()?;

        Ok(())
    }

    /// Start resource monitoring
    fn start_resource_monitoring(&self) -> Result<()> {
        let node_id = self.local_node.id.clone();
        let config = Arc::clone(&self.config);  // ✅ Cheap Arc clone instead of data clone
        let (_shutdown_tx, shutdown_rx) = tokio::sync::mpsc::channel(1);

        tokio::spawn(async move {
            ResourceMonitor::start_monitoring(node_id, config, shutdown_rx).await;
        });

        Ok(())
    }

    /// Start network monitoring
    fn start_network_monitoring(&self) -> Result<()> {
        let node_id = self.local_node.id.clone();
        let target_nodes: Vec<(String, String)> = self
            .known_nodes
            .read()
            .values()
            .map(|node| (node.id.clone(), node.address.clone()))
            .collect();

        let (_shutdown_tx, shutdown_rx) = tokio::sync::mpsc::channel(1);

        tokio::spawn(async move {
            let _ = NetworkManager::start_network_monitoring(node_id, target_nodes, shutdown_rx);
        });

        Ok(())
    }

    /// Get federation statistics
    #[must_use]
    pub fn get_federation_stats(&self) -> FederationStats {
        let nodes = self.known_nodes.read();
        let services = self.registered_services.read();

        let mut stats = FederationStats {
            total_nodes: u32::try_from(nodes.len()).unwrap_or(u32::MAX) + 1, // +1 for local node
            total_services: u32::try_from(services.len()).unwrap_or(u32::MAX),
            ..Default::default()
        };

        // Count node types
        for node in nodes.values() {
            match node.node_type {
                NodeType::Compute => stats.compute_nodes += 1,
                NodeType::Storage => stats.storage_nodes += 1,
                NodeType::Gateway => stats.gateway_nodes += 1,
                NodeType::Hybrid => stats.hybrid_nodes += 1,
                NodeType::Orchestrator => stats.orchestrator_nodes += 1,
            }

            stats.total_cpu_cores += node.resources.cpu_cores;
            stats.total_memory_gb += node.resources.memory_total_gb;
            stats.total_storage_gb += node.storage_capacity.total_capacity_gb;
        }

        // Include local node in counts
        match self.local_node.node_type {
            NodeType::Compute => stats.compute_nodes += 1,
            NodeType::Storage => stats.storage_nodes += 1,
            NodeType::Gateway => stats.gateway_nodes += 1,
            NodeType::Hybrid => stats.hybrid_nodes += 1,
            NodeType::Orchestrator => stats.orchestrator_nodes += 1,
        }

        stats.total_cpu_cores += self.local_node.resources.cpu_cores;
        stats.total_memory_gb += self.local_node.resources.memory_total_gb;

        stats
    }
}

#[async_trait]
impl ServiceDiscovery for SongbirdDiscovery {
    // ServiceDiscovery trait methods

    async fn register(&self, service: ServiceInfo) -> Result<()> {
        let service_id = service.service_id.clone();

        tracing::info!(
            service_id = %service_id,
            "Registering service with Songbird discovery"
        );

        self.registered_services.write().insert(service_id, service);
        Ok(())
    }

    async fn unregister(&self, service_id: &str) -> Result<()> {
        tracing::info!(
            service_id = %service_id,
            "Unregistering service from Songbird discovery"
        );

        self.registered_services.write().remove(service_id);
        Ok(())
    }

    async fn discover(&self, query: ServiceQuery) -> Result<Vec<ServiceInfo>> {
        let services = self.registered_services.read();
        let mut results = Vec::new();

        for service in services.values() {
            if Self::service_matches_query(service, &query) {
                results.push(service.clone());
            }
        }

        Ok(results)
    }

    async fn watch(
        &self,
        _query: ServiceQuery,
    ) -> Result<Pin<Box<dyn Stream<Item = ServiceEvent> + Send>>> {
        let receiver = self.event_sender.subscribe();

        // Create a simple stream from the broadcast receiver
        use futures_util::stream;
        let stream = stream::unfold(receiver, |mut rx| async move {
            match rx.recv().await {
                Ok(event) => Some((event, rx)),
                Err(_) => None,
            }
        });

        Ok(Box::pin(stream))
    }

    async fn update_health(&self, service_id: &str, health: ServiceHealthStatus) -> Result<()> {
        if let Some(service) = self.registered_services.write().get_mut(service_id) {
            service.metadata.insert("health_status".to_string(), format!("{:?}", health).into());
        }

        // Send health update event
        let _ = self.event_sender.send(ServiceEvent::ServiceHealthChanged {
            service_id: service_id.to_string(),
            health,
        });

        Ok(())
    }

    async fn list_all(&self) -> Result<Vec<ServiceInfo>> {
        Ok(self.registered_services.read().values().cloned().collect())
    }

    async fn exists(&self, service_id: &str) -> Result<bool> {
        Ok(self.registered_services.read().contains_key(service_id))
    }

    async fn is_registered(&self, service_id: &str) -> Result<bool> {
        self.exists(service_id).await
    }

    async fn update_metadata(
        &self,
        service_id: &str,
        metadata: HashMap<String, String>,
    ) -> Result<()> {
        if let Some(service) = self.registered_services.write().get_mut(service_id) {
            for (key, value) in metadata {
                service.metadata.insert(key, value.into());
            }
        }
        Ok(())
    }

    fn as_any(&self) -> &dyn std::any::Any {
        self
    }
}

impl SongbirdDiscovery {
    /// Check if a service matches the query criteria
    fn service_matches_query(service: &ServiceInfo, query: &ServiceQuery) -> bool {
        // Check service ID filter
        if let Some(ref service_id) = query.service_id {
            if service.service_id != *service_id {
                return false;
            }
        }

        // Check service type filter
        if let Some(ref service_type) = query.service_type {
            if service.service_type != *service_type {
                return false;
            }
        }

        // Check name filter
        if let Some(ref name_filter) = query.name {
            if !service.name.to_lowercase().contains(&name_filter.to_lowercase()) {
                return false;
            }
        }

        // Check tag filters
        for required_tag in &query.tags {
            if !service.tags.contains(required_tag) {
                return false;
            }
        }

        // Check version requirements
        if let Some(ref version_req) = query.version {
            if !Self::check_version_requirement(&service.version, version_req) {
                return false;
            }
        }

        // Check metadata filters
        for (key, expected_value) in &query.metadata {
            if let Some(service_value) = service.metadata.get(key) {
                if service_value != expected_value {
                    return false;
                }
            } else {
                return false;
            }
        }

        true
    }

    /// Check if a service version matches a requirement
    fn check_version_requirement(service_version: &str, requirement: &str) -> bool {
        if let Some(req_version) = requirement.strip_prefix(">=") {
            service_version >= req_version
        } else if let Some(req_version) = requirement.strip_prefix("<=") {
            service_version <= req_version
        } else if let Some(req_version) = requirement.strip_prefix(">") {
            service_version > req_version
        } else if let Some(req_version) = requirement.strip_prefix("<") {
            service_version < req_version
        } else if let Some(req_version) = requirement.strip_prefix("=") {
            service_version == req_version
        } else {
            // If no operator, assume exact match
            service_version == requirement
        }
    }
}

// Additional service management methods (separate from ServiceDiscovery trait)
impl SongbirdDiscovery {
    /// Register a service with the discovery system
    ///
    /// # Errors
    ///
    /// Returns an error if the service registration fails or if there are
    /// issues with the underlying discovery backend.
    pub fn register_service(&self, service: &ServiceInfo) -> Result<()> {
        let service_id = service.service_id.clone();

        tracing::info!(
            service_id = %service_id,
            service_type = %service.service_type,
            "Registering service with Songbird Discovery"
        );

        self.registered_services.write().insert(service_id.clone(), service.clone());

        // Service registered successfully - event broadcasting handled by federation layer
        tracing::debug!("Service registered: {}", service_id);

        Ok(())
    }

    /// Unregister a service from the discovery system
    ///
    /// # Errors
    ///
    /// Returns an error if the service deregistration fails or if there are
    /// issues with the underlying discovery backend.
    pub fn unregister_service(&self, service_id: &str) -> Result<()> {
        tracing::info!(service_id = %service_id, "Unregistering service from Songbird Discovery");

        self.registered_services.write().remove(service_id);

        // Service unregistered successfully - event broadcasting handled by federation layer
        tracing::debug!("Service unregistered: {}", service_id);

        Ok(())
    }
}

use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};
use std::collections::HashMap;

use crate::traits::discovery::ServiceHealthStatus;
use crate::traits::service::ServiceInfo;

/// Node ID for identifying unique nodes in the federation
pub type NodeId = String;

/// Federation discovery protocol messages
#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum FederationMessage {
    /// Node announces itself to the federation
    NodeAnnouncement {
        node: Box<NodeInfo>,
        timestamp: DateTime<Utc>,
    },
    /// Request for node information
    NodeDiscoveryRequest {
        sender_id: NodeId,
    },
    /// Response to discovery request
    NodeDiscoveryResponse {
        nodes: Vec<NodeInfo>,
    },
    /// Periodic heartbeat
    Heartbeat {
        node_id: NodeId,
        resource_usage: ResourceUsage,
    },
    /// Service advertisement
    ServiceAdvertisement {
        services: Vec<ServiceInfo>,
    },
}

/// Local node information
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct LocalNode {
    pub id: NodeId,
    pub node_type: NodeType,
    pub institution: Option<String>,
    pub resources: ComputeResources,
    pub network_location: NetworkLocation,
    pub created_at: DateTime<Utc>,
}

/// Information about a node in the federation
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct NodeInfo {
    /// Basic identification
    pub id: NodeId,
    pub node_type: NodeType,
    pub institution: Option<String>,
    pub address: String,

    /// Compute capabilities
    pub resources: ComputeResources,
    pub current_load: ResourceUsage,

    /// Data capabilities
    pub available_datasets: Vec<DatasetInfo>,
    pub storage_capacity: StorageInfo,

    /// Federation metadata
    pub trust_level: TrustLevel,
    pub reputation_score: f64,

    /// Network optimization
    pub bandwidth_measurements: HashMap<NodeId, f64>, // Mbps
    pub latency_measurements: HashMap<NodeId, f64>, // ms

    /// Operational
    pub last_seen: DateTime<Utc>,
    pub health_status: ServiceHealthStatus,
    pub services: Vec<String>, // Service IDs hosted on this node
}

/// Type of node in the federation
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub enum NodeType {
    /// Compute-focused node (CPUs, GPUs,
    Compute,
    /// Storage-focused node (large datasets)
    Storage,
    /// Gateway node (connects institutions)
    Gateway,
    /// Hybrid node (compute + storage)
    Hybrid,
    /// Orchestrator node (management)
    Orchestrator,
}

/// Compute resource description
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ComputeResources {
    pub cpu_cores: u32,
    pub cpu_architecture: String, // "x86_64", "ARM64", etc."
    pub memory_total_gb: u64,
    pub memory_available_gb: u64,
    pub gpu_info: Vec<GpuInfo>,
    pub storage_devices: Vec<StorageDevice>,
    pub network_bandwidth_mbps: f64,
}

/// GPU information for scientific computing
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct GpuInfo {
    pub model: String,                      // "NVIDIA A100", "AMD MI250X""
    pub memory_gb: u32,                     // GPU memory
    pub compute_capability: Option<String>, // For CUDA compatibility
    pub utilization_percent: f32,
}

/// Storage device information
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct StorageDevice {
    pub device_type: String, // "NVMe", "SSD", "HDD""
    pub capacity_gb: u64,
    pub available_gb: u64,
    pub mount_point: String,
    pub performance_tier: StoragePerformanceTier,
}

/// Performance classification for storage
#[derive(Debug, Clone, Serialize, Deserialize, Hash, Eq, PartialEq)]
pub enum StoragePerformanceTier {
    HighPerformance, // NVMe, fast SSDs
    Standard,        // Regular SSDs
    Archive,         // HDDs, bulk storage
}

/// Current resource usage
#[derive(Debug, Clone, Serialize, Deserialize, Default)]
pub struct ResourceUsage {
    pub cpu_utilization_percent: f32,
    pub memory_used_gb: u64,
    pub gpu_utilization: Vec<f32>, // Per-GPU utilization
    pub storage_used_gb: u64,
    pub network_utilization_percent: f32,
    pub active_jobs: u32,
}

/// Scientific dataset information
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct DatasetInfo {
    pub id: String,
    pub name: String,
    pub dataset_type: DatasetType,
    pub size_bytes: u64,
    pub format: String, // "FASTA", "FASTQ", "BAM", "VCF", etc."
    pub checksum: String,
    pub access_level: AccessLevel,
    pub last_updated: DateTime<Utc>,
}

/// Scientific dataset types
#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum DatasetType {
    Genomic,
    Proteomic,
    Imaging,
    Metabolomic,
    Clinical,
    Environmental,
    Other(String),
}

/// Data access levels
#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum AccessLevel {
    Public,        // Openly available
    Institutional, // Within institution only
    Consortium,    // Multi-institutional consortium
    Private,       // Restricted access
}

/// Storage capacity information
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct StorageInfo {
    pub total_capacity_gb: u64,
    pub available_capacity_gb: u64,
    pub performance_tier_breakdown: HashMap<StoragePerformanceTier, u64>,
}

/// Trust level in federation
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, PartialOrd, Ord, Eq, Default)]
pub enum TrustLevel {
    #[default]
    Unknown,
    Basic,
    Verified,
    Institutional,
    Consortium,
}

/// Network location for optimization
#[derive(Debug, Clone, Serialize, Deserialize)]
