        Self {
            request_id,
            status: ResponseStatus::Success,
            headers: HashMap::new(),
            body: None,
            timestamp: Utc::now(),
            processing_time: Duration::from_millis(0),
            error_message: None,
            metadata: HashMap::new(),
        }
    }

