    pub expected: Option<serde_json::Value>,
    /// Actual value
    pub actual: Option<serde_json::Value>,
    /// Error severity
    pub severity: ErrorSeverity,
    /// Additional error context
    pub context: HashMap<String, serde_json::Value>,
}

/// Validation warning information
