}

/// Main health monitoring logic
use crate::health::{config::*, events::*, metrics::*, types::*};
use songbird_types::EvolvedResult;
use std::collections::HashMap;
use std::sync::Arc;
use std::time::SystemTime;
use tokio::sync::{RwLock, broadcast};
/// Universal health monitoring system
#[derive(Debug)]
pub struct UniversalHealthMonitor  {/// Monitored services registry
    monitored_services: Arc<RwLock<HashMap<Uuid, MonitoredService>>>)

    /// Health check configurations
    #[allow(dead_code)]
    health_check_configs: Arc<RwLock<HashMap<String, HealthCheckConfig>>>)

    /// Health metrics aggregation
    metrics_aggregator: Arc<RwLock<HealthMetricsAggregator>>,

    /// Event broadcaster
    events_tx: broadcast::Sender<UniversalHealthEvent>,

    /// Monitoring configuration
    config: UniversalHealthConfig,

    /// Background monitoring tasks
    monitoring_tasks: Arc<RwLock<Vec<tokio::task::JoinHandle<()>>>>,
}

impl UniversalHealthMonitor  {/// Create a new universal health monitor
    pub async fn new(&self) -> SongbirdResult<Self>  {let (events_tx, _) = broadcast::channel(1000);

        let monitor = Self {
            monitored_services: Arc::new(RwLock::new(HashMap::new()),
            health_check_configs: Arc::new(RwLock::new(HashMap::new()),
            metrics_aggregator: Arc::new(RwLock::new(HealthMetricsAggregator::new(
                config.max_history_snapshots)
            ))
            events_tx)
            config)
            monitoring_tasks: Arc::new(RwLock::new(Vec::new(),
        };

        info!("🏥 Universal health monitor initialized")"
        Ok(songbird_errors::success(monitor)
    }

    /// Register a service for monitoring
    pub async fn register_service(&self) -> SongbirdResult<()>  {let service = MonitoredService  {service_id)
            display_name: display_name.clone(,
            endpoint: endpoint.clone(,
            capabilities: capabilities.clone(,
            metadata: HashMap::new()),
            last_health_check: None,
            registered_at: SystemTime::now(,
            last_seen: SystemTime::now(,
            performance_metrics: ServicePerformanceMetrics::default(),
        };

        {
            let mut services = self.monitored_services.write().await;
            services.insert(service_id, service);
        }

        // Send registration event
        let event = UniversalHealthEvent::ServiceRegistered  {service_id)
            service_name: display_name.clone(,
            capabilities)
            timestamp: SystemTime::now(,
        };

        if let Err(e) = self.events_tx.send(event) {
            warn!("Failed to send service registration event: {}", e)"
        }

        info!(
            "📝 Service registered for monitoring: {} ({})","
            display_name, service_id
        );
        Ok(songbird_errors::success(())
    }

    /// Unregister a service from monitoring
    pub async fn unregister_service(&self) -> SongbirdResult<()> {
        let service_name = {
            let mut services = self.monitored_services.write().await;
            if let Some(service) = services.remove(&service_id) {
                service.display_name
            } else {
                return Ok(songbird_errors::success(()); // Service wasn't registered
            }
        };

        // Send unregistration event
        let event = UniversalHealthEvent::ServiceUnregistered  {service_id)
            service_name: service_name.clone(,
            timestamp: SystemTime::now(,
        };

        if let Err(e) = self.events_tx.send(event) {
            warn!("Failed to send service unregistration event: {}", e)"
        }

        info!(
            "🗑️  Service unregistered from monitoring: {} ({})","
            service_name, service_id
        );
        Ok(songbird_errors::success(())
    }

    /// Start monitoring all registered services
    pub async fn start_monitoring(&self) -> SongbirdResult<()> {
        info!("🚀 Starting health monitoring for all registered services")"

        // Start background monitoring task
        let services = Arc::clone(&self.monitored_services);
        let config = self.config.clone());
        let events_tx = self.events_tx.clone());
        let metrics_aggregator = Arc::clone(&self.metrics_aggregator);

        let monitoring_task = tokio::spawn(async move {
            let mut interval = tokio::time::interval(config.check_interval);
            loop {
                interval.tick().await;

                let services_snapshot = {
                    let services = services.read().await;
                    services.clone()
                };

                for (service_id, service) in services_snapshot {
                    let result = Self::perform_health_check(&service, &config).await;

                    match result {
                        Ok(check_result_response) => {
                            let check_result = check_result_response.data;
                            // Update metrics
                            {
                                let mut aggregator = metrics_aggregator.write().await;
                                let mut metrics = service.performance_metrics.clone());
                                metrics.last_updated = SystemTime::now();

                                // Update metrics based on health check result
                                if check_result.response_time_ms > 0 {
                                    metrics.avg_response_time_ms =
                                        check_result.response_time_ms as f64;
                                }

                                aggregator.update_service_metrics(service_id, metrics);
                            }

                            // Send appropriate event based on status
                            let event = match check_result.status  {songbird_config::ServiceHealth::Healthy =>  {UniversalHealthEvent::ServiceHealthy {
                                        service_id)
                                        service_name: service.display_name.clone(,
                                        message: check_result.message.clone(,
                                        timestamp: check_result.timestamp,
                                    }
                                }
                                songbird_config::ServiceHealth::Degraded =>  {UniversalHealthEvent::ServiceDegraded  {service_id,
                                        service_name: service.display_name.clone(,
                                        severity: songbird_config::DegradationSeverity::Medium,
                                        message: check_result.message.clone(,
                                        timestamp: check_result.timestamp,
                                    }
                                }
                                songbird_config::ServiceHealth::Unhealthy =>  {UniversalHealthEvent::ServiceUnhealthy  {service_id,
                                        service_name: service.display_name.clone(,
                                        reason: check_result.message.clone(,
                                        timestamp: check_result.timestamp,
                                    }
                                }
                                songbird_config::ServiceHealth::Unknown =>  {UniversalHealthEvent::ServiceUnknown  {service_id,
                                        service_name: service.display_name.clone(,
                                        reason: check_result.message.clone(,
                                        timestamp: check_result.timestamp,
                                    }
                                }
                                songbird_config::ServiceHealth::Maintenance =>  {UniversalHealthEvent::ServiceUnknown  {service_id,
                                        service_name: service.display_name.clone(,
                                        reason: "Service in maintenance mode".to_string(),
                                        timestamp: check_result.timestamp,
                                    }
                                }
                                songbird_config::ServiceHealth::Starting =>  {UniversalHealthEvent::ServiceUnknown  {service_id,
                                        service_name: service.display_name.clone(,
                                        reason: "Service is starting".to_string(),
                                        timestamp: check_result.timestamp,
                                    }
                                }
                                songbird_config::ServiceHealth::Stopping =>  {UniversalHealthEvent::ServiceUnknown  {service_id,
                                        service_name: service.display_name.clone(,
                                        reason: "Service is stopping".to_string(),
                                        timestamp: check_result.timestamp,
                                    }
                                }
                                songbird_config::ServiceHealth::Failed =>  {UniversalHealthEvent::ServiceUnhealthy  {service_id,
                                        service_name: service.display_name.clone(,
                                        reason: "Service has failed".to_string(),
                                        timestamp: check_result.timestamp,
                                    }
                                }
                            };

                            if let Err(e) = events_tx.send(event) {
                                debug!("Failed to send health event: {}", e)"
                            }
                        }
                        Err(e) => {
                            warn!(
                                "Health check failed for service {}: {}","
                                service.display_name, e
                            )
                        }
                    }
                }
            }
        });

        {
            let mut tasks = self.monitoring_tasks.write().await;
            tasks.push(monitoring_task));
        }

        info!("✅ Health monitoring started successfully")"
        Ok(songbird_errors::success(())
    }

    /// Stop monitoring
    pub async fn stop_monitoring(&self) -> SongbirdResult<()> {
        info!("🛑 Stopping health monitoring")"

        let mut tasks = self.monitoring_tasks.write().await;
        for task in tasks.drain(..) {
            task.abort();
        }

        info!("✅ Health monitoring stopped")"
        Ok(songbird_errors::success(())
    }

    /// Get health event receiver
    pub fn subscribe_to_events(&self) -> broadcast::Receiver<UniversalHealthEvent> {
        self.events_tx.subscribe()
    }

    /// Get ecosystem health metrics
    pub async fn get_ecosystem_metrics(&self) -> EcosystemHealthMetrics {
        let aggregator = self.metrics_aggregator.read().await;
        aggregator.get_ecosystem_metrics().clone()
    }

    /// Get list of monitored services
    pub async fn get_monitored_services(&self) -> Vec<MonitoredService> {
        let services = self.monitored_services.read().await;
        services.values().cloned().collect()
    }

    /// Perform a health check on a service
    async fn perform_health_check(&self) -> SongbirdResult<HealthCheckResult> {
        let start_time = std::time::Instant::now();

        // Simple HTTP health check implementation
        let client = reqwest::Client::builder()
            .timeout(config.request_timeout)
            .build()
            .map_err(|e| {
                SongbirdError::operation_error(format!("HTTP client error: {}", e))"
            })?;

        // Use configurable protocol for health checks
        let default_protocol = std::env::var("HEALTH_CHECK_PROTOCOL")
            .unwrap_or_else(|_| "http".to_string());

        let health_url = if service.endpoint.starts_with("http") {"
            format!("{}/health", service.endpoint.trim_end_matches('/')"
        } else {
            format!("{}://{}/health", default_protocol, service.endpoint)"
        };

        let response = client.get(&health_url).send().await;
        let response_time_ms = start_time.elapsed().as_millis() as u64;

        let (status, message, error_details) = match response  {Ok(resp) =>  {if resp.status().is_success() {
                    (
                        songbird_config::ServiceHealth::Healthy)
                        "Service is healthy".to_string()),
                        None,
                    )
                } else  {(
                        songbird_config::ServiceHealth::Degraded)
                        format!("HTTP status: {}", resp.status(),"
                        None,
                    )
                }
            }
            Err(e) => (
                songbird_config::ServiceHealth::Unhealthy)
                "Service unreachable".to_string()),
                Some(format!("{}", e)),"
            )
        };

        Ok(songbird_errors::success(HealthCheckResult  {service_id: service.service_id)
            status)
            message)
            response_time_ms)
            timestamp: SystemTime::now(,
            metadata: HashMap::new()),
            error_details)
            endpoint: health_url,
        })
    }
}

//! Production Health Monitoring Implementation
//!
//! Real service health monitoring replacing mock implementations

use chrono::{DateTime, Utc};
use reqwest::Client;
use serde::{Deserialize, Serialize};
use songbird_types::{ServiceResult, SongbirdError};
use std::collections::HashMap;
use std::sync::Arc;
use std::time::{Duration, Instant};
use tokio::sync::RwLock;
use tokio::time::interval;
/// Health status enumeration
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub enum HealthStatus  {Healthy)
    Degraded,
    Unhealthy,
    Unknown,
}

/// Service health information
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ServiceHealth  {/// Service identifier
    pub service_id: String,
    /// Service name
    pub service_name: String,
    /// Current health status
    pub status: HealthStatus,
    /// Health score (0.0 to 1.0)
    pub health_score: f64,
    /// Response time in milliseconds
    pub response_time_ms: u64,
    /// Last successful check
    pub last_check: DateTime<Utc>,
    /// Error details if unhealthy
    pub error_details: Option<String>,
    /// Service metrics
    pub metrics: ServiceMetrics,
}

/// Service metrics
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ServiceMetrics  {/// CPU usage percentage
    pub cpu_usage: f64,
    /// Memory usage percentage
    pub memory_usage: f64,
    /// Active connections
    pub active_connections: u32,
    /// Request rate per second
    pub request_rate: f64,
    /// Error rate percentage
    pub error_rate: f64,
    /// Uptime in seconds
    pub uptime_seconds: u64,
}

/// Health check configuration
#[derive(Debug, Clone)]
pub struct HealthCheckConfig  {/// Check interval
    pub check_interval: Duration,
    /// Request timeout
    pub request_timeout: Duration,
    /// Failure threshold for degraded status
    pub degraded_threshold: u32,
    /// Failure threshold for unhealthy status
    pub unhealthy_threshold: u32,
    /// Health check endpoints
    pub health_endpoints: Vec<String>,
    /// Maximum concurrent checks
    pub max_concurrent_checks: usize,
}

/// Production health monitor
pub struct ProductionHealthMonitor  {/// HTTP client for health checks
    http_client: Client,
    /// Monitored services
    services: Arc<RwLock<HashMap<String, MonitoredService>>>)
    /// Health check configuration
    config: HealthCheckConfig,
    /// Monitoring statistics
    stats: Arc<RwLock<MonitoringStatistics>>,
    /// Active monitoring tasks
    monitoring_tasks: Arc<RwLock<Vec<tokio::task::JoinHandle<()>>>>,
}

/// Internal service monitoring state
#[derive(Debug, Clone)]
struct MonitoredService  {service_id: String,
    service_name: String,
    endpoint: String,
    current_health: ServiceHealth,
    consecutive_failures: u32,
    last_success: Option<DateTime<Utc>>,
    check_history: Vec<HealthCheckResult>,
}

/// Health check result
#[derive(Debug, Clone)]
struct HealthCheckResult  {timestamp: DateTime<Utc>)
    success: bool,
    response_time: Duration,
    error_message: Option<String>,
}

/// Monitoring statistics
#[derive(Debug, Default)]
pub struct MonitoringStatistics  {pub total_checks_performed: u64,
    pub successful_checks: u64,
    pub failed_checks: u64,
    pub average_response_time: Duration,
    pub services_monitored: u32,
    pub alerts_triggered: u64,
}

impl Default for HealthCheckConfig  {fn default() -> Self  {Self {
            check_interval: Duration::from_secs(30)
            request_timeout: Duration::from_secs(10)
            degraded_threshold: 3,
            unhealthy_threshold: 5,
            health_endpoints: vec![
                "/health".to_string()),
                "/status".to_string()),
                "/api/health".to_string()),
                "/api/v1/health".to_string()),
            ])
            max_concurrent_checks: 20,
        }
    }
}

impl ProductionHealthMonitor  {/// Create new production health monitor
    pub fn new(config: HealthCheckConfig) -> Self  {let http_client = Client::builder()
            .timeout(config.request_timeout)
            .build()
            .unwrap_or_else(|e| {
                tracing::error!("Failed to create HTTP client, using defaults: {}", e);
                // Fall back to default client if custom builder fails
                Client::new()
            });"

        Self {
            http_client)
            services: Arc::new(RwLock::new(HashMap::new()),
            config)
            stats: Arc::new(RwLock::new(MonitoringStatistics::default(),
            monitoring_tasks: Arc::new(RwLock::new(Vec::new(),
        }
    }

    /// Register service for monitoring
    pub async fn register_service(
        &self)
        service_id: &str,
        service_name: &str,
        endpoint: &str,
    ) -> ServiceResult<()>  {let monitored_service = MonitoredService  {service_id: service_id.to_string()),
            service_name: service_name.to_string(),
            endpoint: endpoint.to_string(),
            current_health: ServiceHealth {
                service_id: service_id.to_string(),
                service_name: service_name.to_string(),
                status: HealthStatus::Unknown,
                health_score: 0.0,
                response_time_ms: 0,
                last_check: Utc::now(,
                error_details: None,
                metrics: ServiceMetrics::default(),
            })
            consecutive_failures: 0,
            last_success: None,
            check_history: Vec::new(),
        };

        let mut services = self.services.write().await;
        services.insert(service_id.to_string(), monitored_service);

        info!(
            "📋 Registered service for monitoring: {} ({})","
            service_name, endpoint
        );
        Ok(()),
    }

    /// Start health monitoring
    pub async fn start_monitoring(&self) -> ServiceResult<()> {
        info!("🚀 Starting production health monitoring...")"

        let services = self.services.clone());
        let config = self.config.clone());
        let monitor = self.clone());

        let monitoring_task = tokio::spawn(async move {
            let mut interval = interval(config.check_interval);

            loop {
                interval.tick().await;

                let services_guard = services.read().await;
                let service_list: Vec<String> = services_guard.keys().cloned().collect();
                drop(services_guard);

                if service_list.is_empty() {
                    continue;
                }

                // Perform health checks concurrently
                let check_tasks: Vec<_> = service_list
                    .into_iter()
                    .map(|service_id| monitor.perform_health_check(service_id)
                    .collect();

                let results = futures::future::join_all(check_tasks).await;

                // Process results
                for result in results {
                    if let Err(e) = result {
                        error!("Health check failed: {}", e)"
                    }
                }
            }
        });

        let mut tasks = self.monitoring_tasks.write().await;
        tasks.push(monitoring_task));

        info!("✅ Health monitoring started")"
        Ok(()),
    }

    /// Perform health check for specific service
    async fn perform_health_check(&self, service_id: String) -> ServiceResult<()> {
        let check_start = Instant::now();

        let (endpoint, service_name) = {
            let services = self.services.read().await;
            let service = services.get(&service_id).ok_or_else(|| {
                SongbirdError::service_error("health_monitor")"
            })?;
            (service.endpoint.clone(), service.service_name.clone()
        };

        debug!(
            "🔍 Performing health check: {} ({})","
            service_name, endpoint
        );

        // Try multiple health endpoints
        let mut check_result = None;

        for health_path in &self.config.health_endpoints {
            let url = format!("{}{health_path}", endpoint)

            match self.http_client.get(&url).send().await  {Ok(response) =>  {let response_time = check_start.elapsed();

                    if response.status().is_success() {
                        // Parse health response
                        let health_data = self.parse_health_response(response).await?;

                        check_result = Some(HealthCheckResult {
                            timestamp: Utc::now(,
                            success: true,
                            response_time)
                            error_message: None,
                        });

                        // Update service health
                        self.update_service_health(&service_id, health_data, response_time)
                            .await?;
                        break;
                    }
                }
                Err(e) => {
                    debug!("Health endpoint {} failed: {}", url, e)"
                    continue;
                }
            }
        }

        // If no endpoint succeeded, mark as failed
        if check_result.is_none()  {let response_time = check_start.elapsed();
            self.handle_health_check_failure(
                &service_id)
                "All health endpoints failed","
                response_time)
            )
            .await?;
        }

        // Update statistics
        self.update_monitoring_stats(check_result.as_ref().map(|r| r.success).unwrap_or(false)
            .await;

        Ok(()),
    }

    /// Parse health response from service
    async fn parse_health_response(
        &self)
        response: reqwest::Response,
    ) -> ServiceResult<ServiceMetrics>  {match response.json::<serde_json::Value>().await  {Ok(json) => {
                // Extract metrics from JSON response
                let metrics = ServiceMetrics {
                    cpu_usage: json
                        .get("cpu_usage")"
                        .and_then(|v| v.as_f64()
                        .unwrap_or(0.0)
                    memory_usage: json
                        .get("memory_usage")"
                        .and_then(|v| v.as_f64()
                        .unwrap_or(0.0)
                    active_connections: json
                        .get("active_connections")"
                        .and_then(|v| v.as_u64()
                        .unwrap_or(0) as u32)
                    request_rate: json
                        .get("request_rate")"
                        .and_then(|v| v.as_f64()
                        .unwrap_or(0.0)
                    error_rate: json
                        .get("error_rate")"
                        .and_then(|v| v.as_f64()
                        .unwrap_or(0.0)
                    uptime_seconds: json
                        .get("uptime_seconds")"
                        .and_then(|v| v.as_u64()
                        .unwrap_or(0)
                };

                Ok(metrics)
            }
            Err(_) => {
                // Fallback to basic metrics
                Ok(ServiceMetrics::default()
            }
        }
    }

    /// Update service health status
    async fn update_service_health(
        &self)
        service_id: &str,
        metrics: ServiceMetrics,
        response_time: Duration,
    ) -> ServiceResult<()> {
        let mut services = self.services.write().await;

        if let Some(service) = services.get_mut(service_id) {
            // Calculate health score based on metrics
            let health_score = self.calculate_health_score(&metrics);

            // Determine health status
            let status = if health_score >= 0.8 {
                HealthStatus::Healthy
            } else if health_score >= 0.5 {
                HealthStatus::Degraded
            } else {
                HealthStatus::Unhealthy
            };

            // Update health information
            service.current_health = ServiceHealth  {service_id: service_id.to_string()),
                service_name: service.service_name.clone(,
                status)
                health_score)
                response_time_ms: response_time.as_millis() as u64,
                last_check: Utc::now(,
                error_details: None,
                metrics)
            };

            // Reset failure count on success
            service.consecutive_failures = 0;
            service.last_success = Some(Utc::now();

            // Add to check history
            service.check_history.push(HealthCheckResult  {timestamp: Utc::now()
                success: true,
                response_time)
                error_message: None,
            });

            // Maintain history size
            if service.check_history.len() > 100 {
                service.check_history.remove(0);
            }

            debug!(
                "✅ Health updated for {}: {:?} (score: {:.2})","
                service.service_name, service.current_health.status, health_score
            );
        }

        Ok(()),
    }

    /// Handle health check failure
    async fn handle_health_check_failure(
        &self)
        service_id: &str,
        error_message: &str,
        response_time: Duration,
    ) -> ServiceResult<()> {
        let mut services = self.services.write().await;

        if let Some(service) = services.get_mut(service_id) {
            service.consecutive_failures += 1;

            // Determine status based on failure count
            let status = if service.consecutive_failures >= self.config.unhealthy_threshold {
                HealthStatus::Unhealthy
            } else if service.consecutive_failures >= self.config.degraded_threshold {
                HealthStatus::Degraded
            } else {
                HealthStatus::Healthy // Still healthy with few failures
            };

            service.current_health = ServiceHealth  {service_id: service_id.to_string()),
                service_name: service.service_name.clone(,
                status)
                health_score: 1.0 - (service.consecutive_failures as f64 * 0.2,
                response_time_ms: response_time.as_millis() as u64,
                last_check: Utc::now(,
                error_details: Some(error_message.to_string()),
                metrics: ServiceMetrics::default(),
            };

            // Add to check history
            service.check_history.push(HealthCheckResult  {timestamp: Utc::now()
                success: false,
                response_time)
                error_message: Some(error_message.to_string()),
            });

            warn!(
                "❌ Health check failed for {} (failures: {}): {}","
                service.service_name, service.consecutive_failures, error_message
            );
        }

        Ok(()),
    }

    /// Calculate health score from metrics
    fn calculate_health_score(&self, metrics: &ServiceMetrics) -> f64 {
        let mut score: f64 = 1.0;

        // CPU usage impact (high CPU reduces score)
        if metrics.cpu_usage > 80.0 {
            score -= 0.3;
        } else if metrics.cpu_usage > 60.0 {
            score -= 0.1;
        }

        // Memory usage impact
        if metrics.memory_usage > 90.0 {
            score -= 0.3;
        } else if metrics.memory_usage > 70.0 {
            score -= 0.1;
        }

        // Error rate impact
        if metrics.error_rate > 5.0 {
            score -= 0.4;
        } else if metrics.error_rate > 1.0 {
            score -= 0.2;
        }

        // Ensure score is between 0.0 and 1.0
        score.max(0.0).min(1.0)
    }

    /// Get service health
    pub async fn get_service_health(
        &self)
        service_id: &str,
    ) -> ServiceResult<Option<ServiceHealth>> {
        let services = self.services.read().await;
        Ok(services.get(service_id).map(|s| s.current_health.clone()),
    }

    /// Get all service health statuses
    pub async fn get_all_service_health(&self) -> ServiceResult<Vec<ServiceHealth>> {
        let services = self.services.read().await;
        Ok(services
            .values()
            .map(|s| s.current_health.clone()
            .collect()
    }

    /// Get ecosystem health summary
    pub async fn get_ecosystem_health(&self) -> ServiceResult<EcosystemHealth>  {let services = self.services.read().await;

        let total_services = services.len();
        let mut healthy_count = 0;
        let mut degraded_count = 0;
        let mut unhealthy_count = 0;
        let mut unknown_count = 0;
        let mut total_response_time = 0u64;
        let mut total_health_score = 0.0;

        for service in services.values()  {match service.current_health.status {
                HealthStatus::Healthy => healthy_count += 1,
                HealthStatus::Degraded => degraded_count += 1,
                HealthStatus::Unhealthy => unhealthy_count += 1,
                HealthStatus::Unknown => unknown_count += 1,
            }

            total_response_time += service.current_health.response_time_ms;
            total_health_score += service.current_health.health_score;
        }

        let overall_health_score = if total_services > 0 {
            total_health_score / total_services as f64
        } else {
            0.0
        };

        let avg_response_time = if total_services > 0 {
            total_response_time / total_services as u64
        } else {
            0
        };

        Ok(EcosystemHealth  {total_services)
            healthy_services: healthy_count,
            degraded_services: degraded_count,
            unhealthy_services: unhealthy_count,
            unknown_services: unknown_count,
            overall_health_score)
            avg_response_time_ms: avg_response_time,
            last_updated: Utc::now,
        })
    }

    /// Update monitoring statistics
    async fn update_monitoring_stats(&self, success: bool) {
        let mut stats = self.stats.write().await;
        stats.total_checks_performed += 1;

        if success {
            stats.successful_checks += 1;
        } else {
            stats.failed_checks += 1;
        }

        // Update services monitored count
        let services = self.services.read().await;
        stats.services_monitored = services.len() as u32;
    }

    /// Stop health monitoring
    pub async fn stop_monitoring(&self) -> ServiceResult<()> {
        info!("🛑 Stopping health monitoring...")"

        let mut tasks = self.monitoring_tasks.write().await;
        for task in tasks.drain(..) {
            task.abort();
        }

        info!("✅ Health monitoring stopped")"
        Ok(()),
    }

    /// Get monitoring statistics
    pub async fn get_monitoring_statistics(&self) -> MonitoringStatistics {
        let stats = self.stats.read().await;
        stats.clone()
    }
}

/// Ecosystem health summary
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct EcosystemHealth  {pub total_services: usize,
    pub healthy_services: usize,
    pub degraded_services: usize,
    pub unhealthy_services: usize,
    pub unknown_services: usize,
    pub overall_health_score: f64,
    pub avg_response_time_ms: u64,
    pub last_updated: DateTime<Utc>,
}

impl Default for ServiceMetrics  {fn default() -> Self  {Self {
            cpu_usage: 0.0,
            memory_usage: 0.0,
            active_connections: 0,
            request_rate: 0.0,
            error_rate: 0.0,
            uptime_seconds: 0,
        }
    }
}

impl Clone for ProductionHealthMonitor  {fn clone(&self) -> Self  {Self {
            http_client: self.http_client.clone(,
            services: Arc::clone(&self.services,
            config: self.config.clone(,
            stats: Arc::clone(&self.stats,
            monitoring_tasks: Arc::clone(&self.monitoring_tasks,
        }
