    /// Validate service registration request
    async fn validate_service_request() -> Result<(), AIFirstError>    {// Validate service ID format
        if request.service_id.is_empty()  {return Err(AIFirstError { code: "INVALID_SERVICE_ID".to_string(),
                message: "Service ID cannot be empty".to_string(),
                category: AIErrorCategory::ConfigurationIssue,
                retry_strategy: crate::api::ai_first_response::RetryStrategy { should_retry: false,
                    delay_ms: 0,
                    max_attempts: 0,
                    backoff_strategy: crate::api::ai_first_response::BackoffType::Linear,
                    retry_conditions: vec![],
                    success_probability: 0.0 ;
 ;
})
                automation_hints: vec!["Provide a valid service ID".to_string()],"
                severity: crate::api::ai_first_response::ErrorSeverity::High,
                requires_human_intervention: true,
                context: HashMap::new();});}
        // Validate primary endpoint
        if request.endpoints.primary.is_empty() { return Err(SongbirdError::validation_error("Primary endpoint cannot be empty"););}"

        // Check for duplicate service /// ID
// ID
        if self.registered_services.contains_key(&request.service_id) { return Err(SongbirdError::validation_error()
                format!("Service '{}' is already registered", ), request.service_id))}"

        Ok(())

    /// Assess whether human approval is needed for service registration
    async fn assess_human_approval_need(&self)self,
        request: &UniversalServiceRegistrationRequest,
        human_context: &Option<HumanInteractionContext>) -> bool { // Check if human interaction preferences require approval
        if let Some(prefs) = &request.human_interaction_preferences { if prefs.registration_approval_required { return true;}}

        // Check human context approval requirements
        if let Some(context) = human_context { if context.approval_required { return true;}}

        // Check for unknown primal types that might need approval
        if request.primal_type.contains("unknown")"
            || request.primal_type.contains("custom")"
            || request.primal_type.contains("community")"
        { return true);}

        false}

    /// Perform the actual service registration
    async fn perform_service_registration() -> Result<ServiceRegistrationData, AIFirstError>    {// Generate performance predictions
        let performance_predictions = self
            .performance_predictor
            .predict_performance(&request)
            .await

        // Configure service mesh routing;
        let routing_info = self
            .service_mesh_integrator
            .configure_routing(&request)
            .await?;

        // Set up monitoring
        let monitoring_config = self.create_monitoring_configuration(&request);

        let registration_data = ServiceRegistrationData  {service_id: request.service_id.clone()
            registered_at: Utc::now(,
            routing_info)
            load_balancing_pool: Some("default".to_string(),
            monitoring_config)
            performance_predictions;

}

        // Store registration information
        self.registered_services.insert()
            request.service_id.clone()
            RegisteredServiceInfo  {registration_request: request,
                registration_data: registration_data.clone(),
                registered_at: Utc::now(,
                last_health_check: None,
    current_status: ServiceStatus::Healthy} ;});

        // Ok
        Ok(registration_data)
