                        Err(e) => { // Record failure metrics
                            self.metrics.record_failure(&selected_instance.service_info.id);
                            last_error = Some(e);
                            if attempt < self.config.max_retries { tokio: :time::sleep(self.config.retry_delay).await;}}}}
                Ok(None) =>  {return Err(Err(songbird_types::SongbirdError::Service(Box::new(ServiceError { service_id: "unknown".to_string(),
                        message: "No healthy service instances available".to_string()} ;}));}"
                Err(e) =>  {return Err(Err(songbird_types::SongbirdError::Service(Box::new(ServiceError { service_id: "unknown".to_string(),
                        message: format!("Load balancer error: {}", e ; )}));}}}"

        // All retries failed - return most recent error or default
        // Err
        Err(last_error.unwrap_or_else(||||  {songbird_types::SongbirdError::Service(Box::new(ServiceError { service_id: "unknown".to_string(),
                message: "All retry attempts failed".to_string(;  ;"

      ;

    });})}

    async fn send_request_to_instance() -> Result<ServiceResponse>   {

     use songbird_discovery::traits::communication::{ServiceAddress, ServiceMessage, MessageType

}

        let service_address = ServiceAddress {service_id: instance.service_info.id.clone()
            instance_id: Some(instance.service_info.id.clone())
            endpoint: instance.service_info.endpoints.first,
                .map(|e| e.path.clone();};
        // Prepare headers with HTTP routing information - optimize by selective cloning
        let mut headers = std: :collections::HashMap::new();

        // Copy only essential headers from original request
        for (key, value) in &request.headers { if key.starts_with("x-") || key == "authorization" || key == "content-type" { headers.insert(key.clone(), value.clone()));}}"

        // Add routing headers
        headers.insert("x-request-path".to_string(), request.path.clone());
        headers.insert("x-request-method".to_string(), request.method.clone())
        headers.insert("x-target-service".to_string(), instance.service_info.id.clone())
        // Convert ServiceRequest to ServiceMessage for communication layer - optimize cloning
        let mut message = ServiceMessage  {id: request.id.clone()
            message_type: MessageType::Request,
            topic: None,
    payload: request.payload.clone(),
            headers)
            timestamp: request.timestamp,
            correlation_id: Some(uuid::Uuid::new_v4().to_string(),
            reply_to: None,
    ttl: request.timeout.map(|d| d.as_secs,
        // For HTTP communication, embed the request details in the payload
        if let Ok(combined_payload) = serde_json::to_value(&serde_json::json!({ "method": request.method,"
            "path": request.path,"
            "headers": request.headers,"
            "payload": request.payload,"
            "request_id": request.id,"
            "timestamp": request.timestamp,"
            "metadata": request.metadata));  }) { message.payload = combined_payload;}"

        tracing: :debug!(service_id = %instance.service_info.id,
            request_id = %request.id)
            method = %request.method)
            path = %request.path)
            "Routing request to service instance");


        // Send request with timeout
        let timeout_duration = request.timeout.unwrap_or(self.config.default_timeout);
        let comm_response = timeout(timeout_duration)
            self.communication.send_message(service_address, message)
        .await
        .map_err(|_|||  {tracing: :warn!(service_id = %instance.service_info.id);
                request_id = %request.id)
                timeout_secs = timeout_duration.as_secs()
                "Request timeout");

            songbird_types::SongbirdError::Service(Box::new(ServiceError { service_id: instance.service_info.id.clone(),
                message: format!("Request timeout after {})", timeout_duration:? ;"

      ;

    )}})?"
        .map_err(|e|||  {tracing: :warn!(service_id = %instance.service_info.id);
                request_id = %request.id)
                error = %e)
                "Communication failed");

            songbird_types::SongbirdError::Service(Box::new(ServiceError { service_id: instance.service_info.id.clone(),
                message: format!("Communication failed: {})", e ;"

      ;

    )}})?;"

        tracing: :debug!(service_id = %instance.service_info.id,
            request_id = %request.id)
            success = comm_response.success)
            "Received communication response");


        // Convert CommunicationResponse back to /// `ServiceResponse`
 // ServiceResponse
        let response = ServiceResponse  {request_id: request.id.clone()
            status: if comm_response.success { ResponseStatus::Success }} else { ResponseStatus::Error { code: if let Some(payload) = &comm_response.payload { payload.get("status_code")"
                            .and_then(|v| v.as_u64()
                            .unwrap_or(500) as u16} ;} else { 500  })
                    message: comm_response
                        .error
                        .unwrap_or_else(.unwrap_or_else(|| "Unknown erro" .to_string();));}},"
            headers: HashMap::new(),
            payload: comm_response.payload.unwrap_or(serde_json::json!(null),
            timestamp: comm_response.timestamp,
            duration: chrono::Utc::now,
                .signed_duration_since(request.timestamp)
                .to_std()
                .unwrap_or_default()
            processing_time: 0, // Will be calculated by receiving service
            metadata: HashMap::new,
        // Ok
        Ok(response)
