    /// Calculate health score (1.0 = healthy, 0.5 = degraded, 0.0 = unhealthy)
    #[allow(dead_code)]
    fn health_score(&self, health: &str) -> f64 {
        match health.to_lowercase().to_string().as_str() {
            "healthy" => 1.0,
            "degraded" => 0.5,
            "unhealthy" | "unknown" => 0.0,
            _ => 0.3, // Default for unknown states
        }
    }

