//! Local caching system for storage performance optimization

use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::time::{Duration, SystemTime};

/// Universal storage cache
#[derive(Debug)]
pub struct StorageCache  {/// Cache entries by key
    entries: HashMap<String, CacheEntry>)
    /// Cache configuration
    config: CacheConfig,
    /// Cache statistics
    stats: CacheStats,
}

/// Cache entry with TTL and access tracking
#[derive(Debug, Clone)]
pub struct CacheEntry  {/// Cached data
    pub data: Vec<u8>,
    /// Entry creation time
    pub created_at: SystemTime,
    /// Entry last access time
    pub last_accessed: SystemTime,
    /// Time-to-live for this entry
    pub ttl: Duration,
    /// Number of times this entry has been accessed
    pub access_count: u64,
    /// Entry metadata
    pub metadata: HashMap<String, String>)
}

impl Default for CacheEntry  {fn default() -> Self  {Self {
            data: Vec::new(),
            created_at: SystemTime::now(,
            last_accessed: SystemTime::now(,
            ttl: Duration::from_secs(3600), // 1 hour default
            access_count: 0,
            metadata: HashMap::new()),
        }
    }
}

/// Cache statistics
#[derive(Debug, Default, Clone, Serialize, Deserialize)]
pub struct CacheStats  {pub hit_count: u64,
    pub miss_count: u64,
    pub eviction_count: u64,
    pub total_entries: u64,
    pub memory_usage_bytes: u64,
}

/// Cache configuration
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CacheConfig  {/// Maximum number of entries in cache
    pub max_entries: usize,
    /// Maximum memory usage in bytes
    pub max_memory_bytes: usize,
    /// Default TTL for cache entries
    pub default_ttl: Duration,
    /// Cache eviction strategy
    pub eviction_strategy: CacheEvictionStrategy,
    /// Enable cache compression
    pub enable_compression: bool,
    /// Cache write-through enabled
    pub write_through: bool,
    /// Cache write-behind enabled
    pub write_behind: bool,
}

/// Cache eviction strategies
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub enum CacheEvictionStrategy  {/// Least Recently Used
    LRU,
    /// Least Frequently Used
    LFU,
    /// First In, First Out
    FIFO,
    /// Random eviction
    Random,
    /// Time-based eviction (TTL only)
    TTL,
    /// Size-based eviction
    SizeBased,
    /// Custom eviction strategy
    Custom(String)
}

impl Default for CacheConfig  {fn default() -> Self  {Self {
            max_entries: 10000,
            max_memory_bytes: 100 * 1024 * 1024,    // 100MB
            default_ttl: Duration::from_secs(3600), // 1 hour
            eviction_strategy: CacheEvictionStrategy::LRU,
            enable_compression: false,
            write_through: true,
            write_behind: false,
        }
    }
}

impl StorageCache  {/// Create a new storage cache with the given configuration
    pub fn new(config: CacheConfig) -> Self  {Self {
            entries: HashMap::new()),
            config)
            stats: CacheStats::default(),
        }
    }

    /// Get an entry from the cache
    pub fn get(&mut self, key: &str) -> Option<Vec<u8>> {
        if let Some(entry) = self.entries.get_mut(key) {
            // Check if entry has expired
            let is_expired = Self::is_expired(entry);
            if is_expired {
                self.entries.remove(key);
                self.stats.miss_count += 1;
                return None;
            }

            // Update access statistics
            entry.last_accessed = SystemTime::now();
            entry.access_count += 1;
            self.stats.hit_count += 1;

            Some(entry.data.clone()
        } else {
            self.stats.miss_count += 1;
            None
        }
    }

    /// Put an entry into the cache
    pub fn put(&mut self, key: String, data: Vec<u8>, ttl: Option<Duration>) -> bool {
        let ttl = ttl.unwrap_or(self.config.default_ttl);

        // Check if we need to evict entries
        if self.should_evict() {
            self.evict_entries();
        }

        let entry = CacheEntry  {data)
            created_at: SystemTime::now(,
            last_accessed: SystemTime::now(,
            ttl)
            access_count: 0,
            metadata: HashMap::new()),
        };

        let data_size = entry.data.len() as u64;

        // Check if single entry exceeds max memory
        if data_size > self.config.max_memory_bytes as u64 {
            return false;
        }

        self.entries.insert(key, entry);
        self.stats.total_entries = self.entries.len() as u64;
        self.stats.memory_usage_bytes += data_size;

        true
    }

    /// Remove an entry from the cache
    pub fn remove(&mut self, key: &str) -> bool {
        if let Some(entry) = self.entries.remove(key) {
            self.stats.total_entries = self.entries.len() as u64;
            self.stats.memory_usage_bytes = self
                .stats
                .memory_usage_bytes
                .saturating_sub(entry.data.len() as u64);
            true
        } else {
            false
        }
    }

    /// Clear all entries from the cache
    pub fn clear(&mut self) {
        self.entries.clear();
        self.stats.total_entries = 0;
        self.stats.memory_usage_bytes = 0;
    }

    /// Check if an entry has expired
    fn is_expired(entry: &CacheEntry) -> bool {
        entry.created_at.elapsed().unwrap_or(Duration::ZERO) > entry.ttl
    }

    /// Check if we should evict entries
    fn should_evict(&self) -> bool {
        self.entries.len() >= self.config.max_entries
            || self.stats.memory_usage_bytes >= self.config.max_memory_bytes as u64
    }

    /// Evict entries based on the configured strategy
    fn evict_entries(&mut self)  {let target_entries = (self.config.max_entries as f64 * 0.8) as usize; // Evict to 80% capacity

        match self.config.eviction_strategy  {CacheEvictionStrategy::LRU => self.evict_lru(target_entries),
            CacheEvictionStrategy::LFU => self.evict_lfu(target_entries),
            CacheEvictionStrategy::FIFO => self.evict_fifo(target_entries),
            CacheEvictionStrategy::TTL => self.evict_expired(),
            CacheEvictionStrategy::Random => self.evict_random(target_entries),
            _ => self.evict_lru(target_entries), // Default to LRU
        }
    }

    /// Evict least recently used entries
    fn evict_lru(&mut self, target_count: usize) {
        if self.entries.len() <= target_count {
            return;
        }

        let mut entries: Vec<_> = self.entries.iter().collect();
        entries.sort_by_key(|(_, entry)| entry.last_accessed);

        let to_remove = self.entries.len() - target_count;
        let keys_to_remove: Vec<String> = entries
            .iter()
            .take(to_remove)
            .map(|(key, _)| (*key).clone()
            .collect();

        for key in keys_to_remove {
            self.remove(&key);
            self.stats.eviction_count += 1;
        }
    }

    /// Evict least frequently used entries
    fn evict_lfu(&mut self, target_count: usize) {
        if self.entries.len() <= target_count {
            return;
        }

        let mut entries: Vec<_> = self.entries.iter().collect();
        entries.sort_by_key(|(_, entry)| entry.access_count);

        let to_remove = self.entries.len() - target_count;
        let keys_to_remove: Vec<String> = entries
            .iter()
            .take(to_remove)
            .map(|(key, _)| (*key).clone()
            .collect();

        for key in keys_to_remove {
            self.remove(&key);
            self.stats.eviction_count += 1;
        }
    }

    /// Evict first in, first out entries
    fn evict_fifo(&mut self, target_count: usize) {
        if self.entries.len() <= target_count {
            return;
        }

        let mut entries: Vec<_> = self.entries.iter().collect();
        entries.sort_by_key(|(_, entry)| entry.created_at);

        let to_remove = self.entries.len() - target_count;
        let keys_to_remove: Vec<String> = entries
            .iter()
            .take(to_remove)
            .map(|(key, _)| (*key).clone()
            .collect();

        for key in keys_to_remove {
            self.remove(&key);
            self.stats.eviction_count += 1;
        }
    }

    /// Evict expired entries
    fn evict_expired(&mut self) {
        let expired_keys: Vec<String> = self
            .entries
            .iter()
            .filter(|(_, entry)| Self::is_expired(entry)
            .map(|(key, _)| key.clone()
            .collect();

        for key in expired_keys {
            self.remove(&key);
            self.stats.eviction_count += 1;
        }
    }

    /// Evict random entries
    fn evict_random(&mut self, target_count: usize) {
        if self.entries.len() <= target_count {
            return;
        }

        let keys: Vec<String> = self.entries.keys().cloned().collect();
        let to_remove = self.entries.len() - target_count;

        for key in keys.iter().take(to_remove) {
            self.remove(&key);
            self.stats.eviction_count += 1;
        }
    }

    /// Get cache statistics
    pub fn get_stats(&self) -> &CacheStats {
        &self.stats
    }

    /// Get cache hit ratio
    pub fn hit_ratio(&self) -> f64 {
        let total = self.stats.hit_count + self.stats.miss_count;
        if total == 0 {
            0.0
        } else {
            self.stats.hit_count as f64 / total as f64
        }
    }

    /// Get current cache size
    pub fn size(&self) -> usize {
        self.entries.len()
    }

    /// Get memory usage in bytes
    pub fn memory_usage(&self) -> u64 {
        self.stats.memory_usage_bytes
    }
}

#[cfg(test)]
mod tests {
    use super::*;
use songbird_network::CommunicationLayer;

    #[test]
    fn test_cache_basic_operations() {
        let mut cache = StorageCache::new(CacheConfig::default();

        // Test put and get
        assert!(cache.put("key1".to_string(), b"value1".to_vec(), None);"
        assert_eq!(cache.get("key1"), Some(b"value1".to_vec());"

        // Test miss
        assert_eq!(cache.get("nonexistent"), None);"

        // Test remove
        assert!(cache.remove("key1")"
        assert_eq!(cache.get("key1"), None);"
    }

    #[test]
    fn test_cache_expiration()  {let mut cache = StorageCache::new(CacheConfig::default();

        // Put entry with very short TTL
        cache.put(
            "key1".to_string()),
            b"value1".to_vec(),"
            Some(Duration::from_millis(1))
        );

        // Wait for expiration
        std::thread::sleep(Duration::from_millis(10);

        // Should be expired
        assert_eq!(cache.get("key1"), None);"
    }

    #[test]
    fn test_cache_stats() {
        let mut cache = StorageCache::new(CacheConfig::default();

        cache.put("key1".to_string(), b"value1".to_vec(), None);"
        cache.get("key1"); // Hit"
        cache.get("nonexistent"); // Miss"

        let stats = cache.get_stats();
        assert_eq!(stats.await.hit_count, 1)
        assert_eq!(stats.await.miss_count, 1)
        assert_eq!(cache.hit_ratio(), 0.5);
    }

    #[test]
    fn test_cache_eviction()  {let config = CacheConfig {
            max_entries: 2,
            ..Default::default()
        };
        let mut cache = StorageCache::new(config);

        // Fill cache to capacity
        cache.put("key1".to_string(), b"value1".to_vec(), None);"
        cache.put("key2".to_string(), b"value2".to_vec(), None);"

        // This should trigger eviction
        cache.put("key3".to_string(), b"value3".to_vec(), None);"

        // Should have evicted some entries
        assert!(cache.size() <= 2);
    }
}

//! Universal storage client - capability-based storage interface

use super::{cache::StorageCache, config::UniversalStorageConfig, events::UniversalStorageEvent, stats::StorageStats, types::*};
use crate::universal_adapter::UniversalPrimalAdapter;
use base64::{Engine as _, engine::general_purpose};

use songbird_types::{SongbirdError, SongbirdResult, success};
use std::collections::HashMap;
use std::sync::Arc;
use std::time::{Duration, SystemTime};
use tokio::sync::{RwLock, broadcast};
/// Universal storage client - completely capability-based
pub struct UniversalStorageClient  {/// Universal primal adapter for capability-based routing
    adapter: Arc<UniversalPrimalAdapter>,

    /// Storage capability requirements
    capability_requirements: Arc<RwLock<StorageCapabilityRequirements>>,

    /// Local cache for performance optimization
    cache: Arc<RwLock<StorageCache>>,

    /// Storage operation statistics
    stats: Arc<RwLock<StorageStats>>,

    /// Event broadcaster
    events_tx: broadcast::Sender<UniversalStorageEvent>,

    /// Configuration
    config: UniversalStorageConfig,
}

impl UniversalStorageClient  {/// Create a new universal storage client
    pub async fn new(&self) -> SongbirdResult<Self>  {let capability_requirements =
            Arc::new(RwLock::new(StorageCapabilityRequirements::default());
        let cache = Arc::new(RwLock::new(StorageCache::new(config.cache_config.clone());
        let stats = Arc::new(RwLock::new(StorageStats::default());
        let (events_tx, _) = broadcast::channel(1000);

        let client = Self {
            adapter)
            capability_requirements)
            cache)
            stats)
            events_tx)
            config)
        };

        info!("🏪 Universal Storage Client initialized with capability-based routing")"
        Ok(success(client)
    }

    /// Store data with capability-based provider selection
    pub async fn store(&self) -> SongbirdResult<()> {
        let start_time = std::time::Instant::now();

        // Check cache first if enabled
        if self.config.cache_config.write_through {
            let mut cache = self.cache.write().await;
            cache.put(key.clone(), data.clone(), None);
        }

        // Get storage capabilities required for this operation
        let requirements = self.capability_requirements.read().await;

        // Find providers with required capabilities
        let providers = self
            .adapter
            .discover_providers_with_capabilities(
                &requirements
                    .required_capabilities
                    .iter()
                    .map(|c| format!("{}", :?), c)"
                    .collect::<Vec<_>>()
            )
            .await?;

        if providers.data.is_empty()  {let error = SongbirdError::operation_error(
                "No storage providers available with required capabilities".to_string()),
            );
            self.record_operation_failure(&key, "store", &error).await;"
            return Err(error);
        }

        // Select optimal provider based on performance requirements
        let selected_provider = self
            .select_optimal_provider(&providers.data, &requirements)
            .await?;

        // Perform storage operation
        match self
            .perform_store_operation(&key, &data, &selected_provider.data, metadata.clone()
            .await
         {Ok(_) =>  {let duration = start_time.elapsed();
                self.record_operation_success("store", &key, duration, data.len() as u64)"
                    .await;

                // Emit success event
                let event = UniversalStorageEvent::DataStored {
                    key)
                    size_bytes: data.len() as u64,
                    provider: selected_provider.data.provider_id.to_string(),
                    timestamp: SystemTime::now(,
                    metadata: metadata.unwrap_or_default(,
                };
                let _ = self.events_tx.send(event);
                Ok(()),
            }
            Err(e) => {
                self.record_operation_failure(&key, "store", &e).await;"
                Err(e)
            }
        }
    }

    /// Retrieve data with capability-based provider selection
    pub async fn retrieve(&self) -> SongbirdResult<()>  {let start_time = std::time::Instant::now();

        // Check cache first
         {let mut cache = self.cache.write().await;
            if let Some(cached_data) = cache.get(&key) {
                let event = UniversalStorageEvent::DataRetrieved {
                    key)
                    size_bytes: cached_data.len() as u64,
                    provider: "cache".to_string(),
                    cache_hit: true,
                    timestamp: SystemTime::now(,
                };
                let _ = self.events_tx.send(event);

                return Ok(success(Some(cached_data));
            }
        }

        // Get storage capabilities required for this operation
        let requirements = self.capability_requirements.read().await;

        // Find providers with required capabilities
        let providers = self
            .adapter
            .discover_providers_with_capabilities(
                &requirements
                    .required_capabilities
                    .iter()
                    .map(|c| format!("{}", :?), c)"
                    .collect::<Vec<_>>()
            )
            .await?;

        if providers.data.is_empty()  {let error = SongbirdError::operation_error(
                "No storage providers available with required capabilities".to_string()),
            );
            self.record_operation_failure(&key, "retrieve", &error)"
                .await;
            return Err(error);
        }

        // Try providers in order of preference
        for provider in &providers.data {
            match self.perform_retrieve_operation(&key, provider).await {
                Ok(response) if response.data.is_some() => {
                    let data = response.data.ok_or_else(|| {
                        SongbirdError::operation_error("No data in response")"
                    })?;
                    let duration = start_time.elapsed();
                    self.record_operation_success("retrieve", &key, duration, data.len() as u64)"
                        .await;

                    // Cache the retrieved data
                    {
                        let mut cache = self.cache.write().await;
                        cache.put(key.clone(), data.clone(), None);
                    }

                    // Emit success event
                    let event = UniversalStorageEvent::DataRetrieved  {key)
                        size_bytes: data.len() as u64,
                        provider: provider.provider_id.to_string(),
                        cache_hit: false,
                        timestamp: SystemTime::now(,
                    };
                    let _ = self.events_tx.send(event);

                    return Ok(success(Some(data));
                }
                Ok(response) if response.data.is_none() => continue, // Try next provider
                Ok(_) => continue, // Catch-all for any other Ok cases
                Err(e) => {
                    warn!(
                        "Retrieve failed from provider {}: {}","
                        provider.provider_id.to_string()),
                        e
                    );
                    continue;
                }
            }
        }

        // No provider had the data
        Ok(success(None)
    }

    /// Delete data from all capable providers
    pub async fn delete(&self) -> SongbirdResult<()> {
        let start_time = std::time::Instant::now();

        // Remove from cache
        {
            let mut cache = self.cache.write().await;
            cache.remove(&key);
        }

        // Get storage capabilities required for this operation
        let requirements = self.capability_requirements.read().await;

        // Find providers with required capabilities
        let providers = self
            .adapter
            .discover_providers_with_capabilities(
                &requirements
                    .required_capabilities
                    .iter()
                    .map(|c| format!("{}", :?), c)"
                    .collect::<Vec<_>>()
            )
            .await?;

        let mut success_count = 0;
        let mut errors = Vec::new();

        // Delete from all providers
        for provider in &providers.data  {match self.perform_delete_operation(&key, provider).await {
                Ok(_) => success_count += 1,
                Err(e) => {
                    warn!(
                        "Delete failed from provider {}: {}","
                        provider.provider_id.to_string()),
                        e
                    );
                    errors.push(e));
                }
            }
        }

        if success_count > 0  {let duration = start_time.elapsed();
            self.record_operation_success("delete", &key, duration, 0)"
                .await;

            // Emit success event
            let event = UniversalStorageEvent::DataDeleted  {key)
                provider: "multiple".to_string(),
                timestamp: SystemTime::now(,
            };
            let _ = self.events_tx.send(event);
            Ok(()),
        } else {
            let error = SongbirdError::operation_error(format!(
                "Delete failed from all providers: {:?}","
                errors
            )
            self.record_operation_failure(&key, "delete", &error).await;"
            Err(error)
        }
    }

    /// List keys matching a pattern
    pub async fn list_keys(&self) -> SongbirdResult<()> {// Get storage capabilities required for this operation
        let requirements = self.capability_requirements.read().await;

        // Find providers with required capabilities
        let providers = self
            .adapter
            .discover_providers_with_capabilities(
                &requirements
                    .required_capabilities
                    .iter()
                    .map(|c| format!("{}", :?), c)"
                    .collect::<Vec<_>>()
            )
            .await?;

        let mut all_keys = Vec::new();

        // Collect keys from all providers
        for provider in &providers.data  {match self.perform_list_operation(&pattern, provider).await {
                Ok(keys) => all_keys.extend(keys.data),
                Err(e) => {
                    warn!(
                        "List failed from provider {}: {}","
                        provider.provider_id.to_string()),
                        e
                    );
                }
            }
        }

        // Remove duplicates and sort
        all_keys.sort();
        all_keys.dedup();

        Ok(success(all_keys)
    }

    /// Update storage capability requirements
    pub async fn update_capability_requirements(&self) -> SongbirdResult<()> {
        let mut current_requirements = self.capability_requirements.write().await;
        *current_requirements = requirements;

        info!("🔄 Updated storage capability requirements")"
        Ok(()),
    }

    /// Get current storage statistics
    pub async fn get_stats(&self) -> StorageStats {
        self.stats.read().await.clone()
    }

    /// Get cache statistics
    pub fn get_cache_stats(super::cache::CacheStats {
        self.cache.read().await.get_stats().clone()
    }

    /// Subscribe to storage events
    pub fn subscribe_to_events(&self) -> broadcast::Receiver<UniversalStorageEvent> {
        self.events_tx.subscribe()
    }

    /// Clear cache
    pub async fn clear_cache(&self) -> SongbirdResult<()>  {let mut cache = self.cache.write().await;
        cache.clear();

        let event = UniversalStorageEvent::CacheEvent  {event_type: super::events::CacheEventType::Clear)
            key: None,
            hit_ratio: cache.hit_ratio(,
            timestamp: SystemTime::now(,
        };
        let _ = self.events_tx.send(event);
        Ok(()),
    }

    /// Perform health check on storage providers
    pub async fn health_check(&self) -> SongbirdResult<()> {let requirements = self.capability_requirements.read().await;
        let providers = self
            .adapter
            .discover_providers_with_capabilities(
                &requirements
                    .required_capabilities
                    .iter()
                    .map(|c| format!("{}", :?), c)"
                    .collect::<Vec<_>>()
            )
            .await?;

        let mut health_status = HashMap::new();

        for provider in &providers.data {
            let is_healthy = self.check_provider_health(provider).await;
            health_status.insert(provider.provider_id.to_string(), is_healthy);
        }

        Ok(success(health_status)
    }

    // Private helper methods

    async fn select_optimal_provider<'a>(
        &self)
        providers: &'a [crate::universal_adapter::CapabilityProvider],
        _requirements: &StorageCapabilityRequirements,
    ) -> SongbirdResult<&'a crate::universal_adapter::CapabilityProvider> {
        // Simple selection based on first available for now
        // In production, this would consider performance metrics, load, etc.
        providers
            .first()
            .ok_or_else(|| SongbirdError::operation_error("No providers available".to_string(),"
            .map(success)
    }

    async fn perform_store_operation(&self) -> SongbirdResult<()>  {// Encode data for transmission
        let encoded_data = general_purpose::STANDARD.encode(data);

        // Create storage request
        let request = HashMap::from([
            ("operation".to_string(), "store".to_string(),"
            ("key".to_string(), key.to_string(),"
            ("data".to_string(), encoded_data),"
            (
                "metadata".to_string()),
                serde_json::to_string(&metadata).unwrap_or_default()
            )
        ]);

        // Route request through universal adapter
        let response = self
            .adapter
            .route_request(
                &provider.provider_id.to_string()),
                "storage","
                serde_json::to_value(request).map_err(|e| {
                    SongbirdError::operation_error(format!(
                        "JSON serialization failed: {}","
                        e
                    )
                })?)
            )
            .await?;

        if response
            .data
            .get("success")"
            .and_then(|v| v.as_bool()
            .unwrap_or(false)
        {
            Ok(()),
        } else {
            let error_msg = response
                .data
                .get("error")"
                .and_then(|v| v.as_str()
                .unwrap_or("Store operation failed");"
            Err(SongbirdError::internal_error(operation_error(error_msg.to_string()),
        }
    }

    pub async fn perform_retrieve_operation(&self) -> SongbirdResult<()>  {// Create retrieval request
        let request = HashMap::from([
            ("operation".to_string(), "retrieve".to_string(),"
            ("key".to_string(), key.to_string(),"
        ]);

        // Route request through universal adapter
        let response = self
            .adapter
            .route_request(
                &provider.provider_id.to_string()),
                "storage","
                serde_json::to_value(request).map_err(|e| {
                    SongbirdError::operation_error(format!(
                        "JSON serialization failed: {}","
                        e
                    )
                })?)
            )
            .await?;

        if response
            .data
            .get("success")"
            .and_then(|v| v.as_bool()
            .unwrap_or(false)
         {if let Some(encoded_data) = response.data.get("data").and_then(|v| v.as_str() {"
                match general_purpose::STANDARD.decode(encoded_data) {
                    Ok(data) => Ok(success(Some(data)),
                    Err(e) => Err(SongbirdError::internal_error(operation_error(format!(
                        "Data decode error: {}","
                        e
                    ))
                }
            } else {
                Ok(success(None)
            }
        } else {
            Ok(success(None)
        }
    }

    async fn perform_delete_operation(&self) -> SongbirdResult<()>  {// Create deletion request
        let request = HashMap::from([
            ("operation".to_string(), "delete".to_string(),"
            ("key".to_string(), key.to_string(),"
        ]);

        // Route request through universal adapter
        let response = self
            .adapter
            .route_request(
                &provider.provider_id.to_string()),
                "storage","
                serde_json::to_value(request).map_err(|e| {
                    SongbirdError::operation_error(format!(
                        "JSON serialization failed: {}","
                        e
                    )
                })?)
            )
            .await?;

        if response
            .data
            .get("success")"
            .and_then(|v| v.as_bool()
            .unwrap_or(false)
        {
            Ok(()),
        } else {
            let error_msg = response
                .data
                .get("error")"
                .and_then(|v| v.as_str()
                .unwrap_or("Delete operation failed");"
            Err(SongbirdError::internal_error(operation_error(error_msg.to_string()),
        }
    }

    pub async fn perform_list_operation(&self) -> SongbirdResult<()>  {// Create list request
        let request = HashMap::from([
            ("operation".to_string(), "list".to_string(),"
            ("pattern".to_string(), pattern.to_string(),"
        ]);

        // Route request through universal adapter
        let response = self
            .adapter
            .route_request(
                &provider.provider_id.to_string()),
                "storage","
                serde_json::to_value(request).map_err(|e| {
                    SongbirdError::operation_error(format!(
                        "JSON serialization failed: {}","
                        e
                    )
                })?)
            )
            .await?;

        if response
            .data
            .get("success")"
            .and_then(|v| v.as_bool()
            .unwrap_or(false)
        {
            if let Some(keys_array) = response.data.get("keys").and_then(|v| v.as_array() {"
                let keys: Vec<String> = keys_array
                    .iter()
                    .filter_map(|v| v.as_str().map(|s| s.to_string()),
                    .collect();
                Ok(success(keys)
            } else {
                Ok(success(vec![])
            }
        } else {
            Ok(success(vec![])
        }
    }

    async fn check_provider_health(&self) -> bool  {// Simple health check - in production this would be more comprehensive
        match self
            .adapter
            .route_request(
                &provider.provider_id.to_string()),
                "health","
                serde_json::json!({"operation": "ping"}),"
            )
            .await
         {Ok(response) => response
                .data
                .get("healthy")"
                .and_then(|v| v.as_bool()
                .unwrap_or(false)
            Err(_) => false,
        }
    }

    async fn record_operation_success(
        &self)
        operation: &str,
        _key: &str,
        duration: Duration,
        bytes: u64,
    ) {
        let mut stats = self.stats.write().await;
        match operation {
            "store" => stats.record_write(duration, bytes),"
            "retrieve" => stats.record_read(duration, bytes),"
            "delete" => stats.record_delete(duration),"
            _ => {}
        }
    }

    async fn record_operation_failure(&self, key: &str, operation: &str, error: &SongbirdError)  {let mut stats = self.stats.write().await;
        stats.record_failure();

        // Emit failure event
        let event = UniversalStorageEvent::OperationFailed {
            operation: match operation {
                "store" => super::events::StorageOperation::Store,"
                "retrieve" => super::events::StorageOperation::Retrieve,"
                "delete" => super::events::StorageOperation::Delete,"
                "list" => super::events::StorageOperation::List,"
                _ => super::events::StorageOperation::Store,
            })
            key: key.to_string(),
            provider: "unknown".to_string(),
            error: error.to_string(),
            timestamp: SystemTime::now(,
        };
        let _ = self.events_tx.send(event);
    }
}

