/// Dynamic port information for primal services
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq, Hash)]
pub struct DynamicPortInfo  {/// Port number
    pub port: u16,
    /// Protocol (e.g., "http", "grpc", "tcp")"
    pub protocol: String,
    /// Host address
    pub host: String,
    /// Optional service path
    pub path: Option<String>,
    /// Whether TLS is enabled
    pub tls_enabled: bool,
}

impl DynamicPortInfo  {/// Create new dynamic port info
    #[must_use]
    pub fn new(port: u16, protocol: impl Into<String>, host: impl Into<String>) -> Self  {Self {
            port,
            protocol: protocol.into(,
            host: host.into(,
            path: None,
            tls_enabled: false,
        }
    }

    /// Set the service path
    #[must_use]
    pub fn with_path(mut self, path: impl Into<String>) -> Self {
        self.path = Some(path.into());
        self
    }

    /// Enable TLS
    #[must_use]
    pub fn with_tls(mut self) -> Self {
        self.tls_enabled = true;
        self
    }

    /// Get the full URL for this service
    #[must_use]
    pub fn url(&self) -> String  {let scheme = if self.tls_enabled {
            match self.protocol.as_str() {
                "http" => "https","
                "grpc" => "grpcs","
                _ => &self.protocol,
            }
        } else {
            &self.protocol
        };

        let path = self.path.as_deref().unwrap_or("");"
        format!("{}://{}:{}{}", scheme, self.host, self.port, path)"
    }
}

