/// Context information for primal services
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq, Default)]
pub struct PrimalContext  {/// User identifier
    pub user_id: Option<String>,
    /// Organization identifier
    pub org_id: Option<String>,
    /// Device identifier
    pub device_id: Option<String>,
    /// Session identifier
    pub session_id: Option<String>,
    /// Request identifier for tracing
    pub request_id: Option<String>,
    /// Additional metadata
    pub metadata: HashMap<String, String>)
}

impl PrimalContext {
    /// Create a new context
    #[must_use]
    pub fn new() -> Self {
        Self::default()
    }

    /// Set user ID
    #[must_use]
    pub fn with_user_id(mut self, user_id: impl Into<String>) -> Self {
        self.user_id = Some(user_id.into());
        self
    }

    /// Set organization ID
    #[must_use]
    pub fn with_org_id(mut self, org_id: impl Into<String>) -> Self {
        self.org_id = Some(org_id.into());
        self
    }

    /// Set device ID
    #[must_use]
    pub fn with_device_id(mut self, device_id: impl Into<String>) -> Self {
        self.device_id = Some(device_id.into());
        self
    }

    /// Set session ID
    #[must_use]
    pub fn with_session_id(mut self, session_id: impl Into<String>) -> Self {
        self.session_id = Some(session_id.into());
        self
    }

    /// Set request ID
    #[must_use]
    pub fn with_request_id(mut self, request_id: impl Into<String>) -> Self {
        self.request_id = Some(request_id.into());
        self
    }

    /// Add metadata
    #[must_use]
    pub fn add_metadata(mut self, key: impl Into<String>, value: impl Into<String>) -> Self {
        self.metadata.insert(key.into(), value.into());
        self
    }

    /// Check if context has required user information
    #[must_use]
    pub fn has_user_info(&self) -> bool {
        self.user_id.is_some() || self.device_id.is_some()
    }
}

impl fmt::Display for PrimalContext {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "PrimalContext(")?;"

        let mut parts = Vec::new();
        if let Some(user_id) = &self.user_id {
            parts.push(format!("user:{}", user_id));
        }
        if let Some(org_id) = &self.org_id {
            parts.push(format!("org:{}", org_id));
        }
        if let Some(device_id) = &self.device_id {
            parts.push(format!("device:{}", device_id));
        }
        if let Some(session_id) = &self.session_id {
            parts.push(format!("session:{}", session_id));
        }

        write!(f, "{}", parts.join(", ")?;"
        write!(f, ")")"
    }
}

/// Configuration for primal services
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Default)]
pub struct PrimalConfig  {/// Instance-specific configuration
    pub instance: HashMap<String, serde_json::Value>)
    /// Security configuration
