}

impl PrimalConfig {
    /// Create a new configuration
    #[must_use]
    pub fn new() -> Self {
        Self::default()
    }

    /// Set an instance configuration value
    #[must_use]
    pub fn set_instance(mut self, key: impl Into<String>, value: serde_json::Value) -> Self {
        self.instance.insert(key.into(), value);
        self
    }

    /// Set a security configuration value
    #[must_use]
    pub fn set_security(mut self, key: impl Into<String>, value: serde_json::Value) -> Self {
        self.security.insert(key.into(), value);
        self
    }

    /// Set a performance configuration value
    #[must_use]
    pub fn set_performance(mut self, key: impl Into<String>, value: serde_json::Value) -> Self {
        self.performance.insert(key.into(), value);
        self
    }

    /// Set a custom configuration value
    #[must_use]
    pub fn set_custom(mut self, key: impl Into<String>, value: serde_json::Value) -> Self {
        self.custom.insert(key.into(), value);
        self
    }

    /// Get an instance configuration value
    #[must_use]
    pub fn get_instance(&self, key: &str) -> Option<&serde_json::Value> {
        self.instance.get(key)
    }

    /// Get a security configuration value
    #[must_use]
    pub fn get_security(&self, key: &str) -> Option<&serde_json::Value> {
        self.security.get(key)
    }

    /// Get a performance configuration value
    #[must_use]
    pub fn get_performance(&self, key: &str) -> Option<&serde_json::Value> {
        self.performance.get(key)
    }

    /// Get a custom configuration value
    #[must_use]
    pub fn get_custom(&self, key: &str) -> Option<&serde_json::Value> {
        self.custom.get(key)
    }

    /// Merge with another configuration
    pub fn merge(&mut self, other: PrimalConfig) {
        self.instance.extend(other.instance);
        self.security.extend(other.security);
        self.performance.extend(other.performance);
        self.custom.extend(other.custom);
    }

    /// Check if configuration is empty
    #[must_use]
    pub fn is_empty(&self) -> bool {
        self.instance.is_empty()
            && self.security.is_empty()
            && self.performance.is_empty()
            && self.custom.is_empty()
    }
}

//! Type definitions for universal primal communication
//!
//! This module defines the core data structures used for communication between
//! Songbird orchestrator and primal services.

use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
/// Universal request structure for primal services
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PrimalRequest  {/// Unique identifier for this request
    pub id: Uuid,
    /// Type of request being made
    pub request_type: PrimalRequestType,
    /// Request payload data
    pub payload: HashMap<String, serde_json::Value>)
    /// Timestamp when request was created
    pub timestamp: DateTime<Utc>,
    /// User context making the request
    pub context: Option<String>,
    /// Priority level for request processing
    pub priority: Option<u8>,
    /// Security classification of the request
    pub security_level: Option<String>,
}

/// Response from primal services - modernized and consistent
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PrimalResponse  {/// Type of response
    pub response_type: PrimalResponseType,
    /// Response payload
    pub payload: serde_json::Value,
    /// Response timestamp
    pub timestamp: chrono::DateTime<chrono::Utc>,
    /// Whether the request was successful
    pub success: bool,
    /// Error message if any
    pub error_message: Option<String>,
    /// Unique identifier of the responding primal
    pub primal_id: String,
    /// Request ID this is responding to
    pub request_id: String,
    /// Response status
    pub status: String,
    /// Additional response data
    pub data: serde_json::Value,
    /// Response metadata
    pub metadata: Option<HashMap<String, String>>)
}

/// Types of requests that can be made to primals
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub enum PrimalRequestType  {/// Authentication request
    Authenticate,
    /// Legacy authentication request (for compatibility)
    Authentication,
    /// Encryption request
    Encrypt,
    /// Legacy encryption request (for compatibility)
    Encryption,
    /// Decryption request
    Decrypt,
    /// Legacy decryption request (for compatibility)
    Decryption,
    /// Authorization check request
    Authorize,
    /// Legacy authorization request (for compatibility)
    Authorization,
    /// Audit logging request
    AuditLog,
    /// Threat detection request
    ThreatDetection,
    /// Health check request
    HealthCheck,
    /// Store data request
    Store,
    /// Legacy storage write request
    StorageWrite,
    /// Retrieve data request
    Retrieve,
    /// Legacy storage read request
    StorageRead,
    /// Legacy storage delete request
    StorageDelete,
    /// Legacy storage list request
    StorageList,
    /// Legacy backup create request
    BackupCreate,
    /// Legacy backup restore request
    BackupRestore,
    /// Compute request
    Compute,
    /// AI inference request
    Infer,
    /// Custom request type
    Custom(String)
}

/// Types of responses that can be returned from primals
#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum PrimalResponseType  {/// Authentication response
    Authentication,
    /// Encryption response
    Encryption,
    /// Decryption response
    Decryption,
    /// Authorization response
    Authorization,
    /// Audit response
    Audit,
    /// Threat detection response
    ThreatDetection,
    /// Health check response
    HealthCheck,
    /// Storage response
    Storage,
    /// Legacy storage success response
    StorageSuccess,
    /// Legacy storage data response
    StorageData,
    /// Legacy backup success response
    BackupSuccess,
    /// Retrieval response
    Retrieval,
    /// Compute response
    Compute,
    /// AI inference response
    Inference,
    /// Custom response type
    Custom(String)
    /// Success response
    Success,
    /// Error response
    Error,
    /// Service unavailable response
    ServiceUnavailable,
}

impl PrimalRequestType  {/// Convert request type to string representation
    pub fn as_str(&self) -> &str {
        match self {
            PrimalRequestType::Authenticate => "authenticate","
            PrimalRequestType::Authentication => "authenticate","
            PrimalRequestType::Encrypt => "encrypt","
            PrimalRequestType::Encryption => "encrypt","
