    /// - Storage operation fails
    async fn register(&mut self, plugin: Plugin) -> SongbirdResult<PluginId>;

    /// Unregister a plugin
    ///
    /// # Errors
    /// Returns an error if:
    /// - Plugin ID not found
    /// - Plugin has dependent plugins
    /// - Storage operation fails
