/// Service event types for broadcasting
#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum ServiceEvent  {ServiceRegistered  {service_id: String,
        service_type: String,
        endpoint: String,
        timestamp: u64,
    })
    ServiceDeregistered  {service_id: String,
        timestamp: u64,
    })
