    pub id: String,
    /// Service name
    pub name: String,
    /// Service endpoint
    pub endpoint: String,
    /// Service capabilities
    pub capabilities: Vec<String>,
    /// Service metadata
    pub metadata: std::collections::HashMap<String, String>,
