/// Performance testing utilities
///
/// Provides benchmarking, performance measurement, and load testing
/// utilities for performance-critical components.
use crate::canonical_test_framework::TestResult;
use songbird_types::SongbirdError;
use std::time::{Duration, Instant};

/// Performance measurement context
pub struct PerformanceMeasurement {
    pub operation_name: String,
    pub start_time: Instant,
    pub measurements: Vec<Duration>,
    pub min_duration: Option<Duration>,
    pub max_duration: Option<Duration>,
}

impl PerformanceMeasurement {
    #[must_use]
    pub fn new(operation_name: &str) -> Self {
        Self {
            operation_name: operation_name.to_string(),
            start_time: Instant::now(),
            measurements: Vec::new(),
            min_duration: None,
            max_duration: None,
        }
    }

    /// Record a single measurement
    pub fn record(&mut self, duration: Duration) {
        self.measurements.push(duration);

        self.min_duration = Some(self.min_duration.map_or(duration, |min| min.min(duration)));

        self.max_duration = Some(self.max_duration.map_or(duration, |max| max.max(duration)));
    }

    /// Get average duration
    #[must_use]
    pub fn average_duration(&self) -> Option<Duration> {
        if self.measurements.is_empty() {
            return None;
        }

        let total_nanos: u64 = self.measurements.iter().map(|d| d.as_nanos() as u64).sum();

        Some(Duration::from_nanos(total_nanos / self.measurements.len() as u64))
    }

    /// Get percentile duration
    #[must_use]
    pub fn percentile_duration(&self, percentile: f32) -> Option<Duration> {
        if self.measurements.is_empty() {
            return None;
        }

        let mut sorted = self.measurements.clone();
        sorted.sort();

        let index = ((percentile / 100.0) * sorted.len() as f32) as usize;
        let index = index.min(sorted.len() - 1);

        Some(sorted[index])
    }

    /// Print performance summary
    pub fn print_summary(&self) {
        println!("Performance Summary for {}:", self.operation_name);
        println!("  Measurements: {}", self.measurements.len());

        if let Some(avg) = self.average_duration() {
            println!("  Average: {avg:?}");
        }

        if let Some(min) = self.min_duration {
            println!("  Min: {min:?}");
        }

        if let Some(max) = self.max_duration {
            println!("  Max: {max:?}");
        }

        if let Some(p95) = self.percentile_duration(95.0) {
            println!("  95th percentile: {p95:?}");
        }

        if let Some(p99) = self.percentile_duration(99.0) {
            println!("  99th percentile: {p99:?}");
        }
    }
}

/// Benchmark a function multiple times
pub async fn benchmark_async<F, Fut, T>(
    name: &str,
    iterations: usize,
    mut operation: F,
) -> TestResult<PerformanceMeasurement>
where
    F: FnMut() -> Fut,
    Fut: std::future::Future<Output = TestResult<T>>,
{
    let mut measurement = PerformanceMeasurement::new(name);

    for i in 0..iterations {
        let start = Instant::now();

        operation().await.map_err(|e| {
            SongbirdError::service("benchmark", format!("Benchmark iteration {} failed: {e}", i))
        })?;

        let duration = start.elapsed();
        measurement.record(duration);
    }

    Ok(measurement)
}

/// Benchmark a synchronous function multiple times
pub fn benchmark_sync<F, T>(
    name: &str,
    iterations: usize,
    mut operation: F,
) -> TestResult<PerformanceMeasurement>
where
    F: FnMut() -> TestResult<T>,
{
    let mut measurement = PerformanceMeasurement::new(name);

    for i in 0..iterations {
        let start = Instant::now();

        operation().map_err(|e| {
            SongbirdError::service("benchmark", format!("Benchmark iteration {} failed: {e}", i))
        })?;

        let duration = start.elapsed();
        measurement.record(duration);
    }

    Ok(measurement)
}

/// Load testing utilities
pub struct LoadTester {
    pub concurrent_users: usize,
    pub test_duration: Duration,
    pub ramp_up_duration: Duration,
}

impl LoadTester {
    #[must_use]
    pub fn new(concurrent_users: usize, test_duration: Duration) -> Self {
        Self {
            concurrent_users,
            test_duration,
            ramp_up_duration: Duration::from_secs(10),
        }
    }

    #[must_use]
    pub fn with_ramp_up(mut self, ramp_up_duration: Duration) -> Self {
        self.ramp_up_duration = ramp_up_duration;
        self
    }

    /// Run a load test with concurrent operations
    pub async fn run_load_test<F, Fut, T>(
        &self,
        name: &str,
        operation: F,
    ) -> TestResult<LoadTestResults>
    where
        F: Fn() -> Fut + Send + Sync + Clone + 'static,
        Fut: std::future::Future<Output = TestResult<T>> + Send + 'static,
        T: Send + 'static,
    {
        let mut results = LoadTestResults::new(name);
        let start_time = Instant::now();

        // Calculate ramp-up delay between users
        let ramp_up_delay = if self.concurrent_users > 1 {
            self.ramp_up_duration / (self.concurrent_users as u32 - 1)
        } else {
            Duration::ZERO
        };

        let mut handles = Vec::new();

        // Spawn concurrent operations with ramp-up
        for i in 0..self.concurrent_users {
            let operation = operation.clone();
            let test_duration = self.test_duration;

            let handle = tokio::spawn(async move {
                let mut user_results = Vec::new();
                let user_start = Instant::now();

                while user_start.elapsed() < test_duration {
                    let op_start = Instant::now();
                    match operation().await {
                        Ok(_) => {
                            user_results.push(LoadTestSample {
                                duration: op_start.elapsed(),
                                success: true,
                                error: None,
                            });
                        }
                        Err(e) => {
                            user_results.push(LoadTestSample {
                                duration: op_start.elapsed(),
                                success: false,
                                error: Some(e.to_string()),
                            });
                        }
                    }

                    // Small delay to prevent overwhelming the system
                    tokio::time::sleep(Duration::from_millis(10)).await;
                }

                user_results
            });

            handles.push(handle);

            // Ramp-up delay
            if i < self.concurrent_users - 1 {
                // Add delay between user spawns for realistic load patterns
            }
            tokio::time::sleep(ramp_up_delay).await;
        }

        // Collect results from all users
        for handle in handles {
            let user_samples = handle.await.map_err(|e| {
                SongbirdError::service("load-test ", format!("Load test task failed: {}", e))
            })?;

            results.samples.extend(user_samples);
        }

        results.total_duration = start_time.elapsed();
        results.calculate_metrics();

        Ok(results)
    }
}

/// Load test results
#[derive(Debug)]
pub struct LoadTestResults {
    pub test_name: String,
    pub samples: Vec<LoadTestSample>,
    pub total_duration: Duration,
    pub success_rate: f32,
    pub average_response_time: Duration,
    pub throughput_per_second: f32,
}

#[derive(Debug)]
pub struct LoadTestSample {
    pub duration: Duration,
    pub success: bool,
    pub error: Option<String>,
}

impl LoadTestResults {
    #[must_use]
    pub fn new(test_name: &str) -> Self {
        Self {
            test_name: test_name.to_string(),
            samples: Vec::new(),
            total_duration: Duration::ZERO,
            success_rate: 0.0,
            average_response_time: Duration::ZERO,
            throughput_per_second: 0.0,
        }
    }

    fn calculate_metrics(&mut self) {
        if self.samples.is_empty() {
            return;
        }

        let successful_samples: Vec<_> = self.samples.iter().filter(|s| s.success).collect();

        self.success_rate = successful_samples.len() as f32 / self.samples.len() as f32;

        if !successful_samples.is_empty() {
            let total_nanos: u64 =
                successful_samples.iter().map(|s| s.duration.as_nanos() as u64).sum();

            self.average_response_time =
                Duration::from_nanos(total_nanos / successful_samples.len() as u64);
        }

        if self.total_duration.as_secs_f32() > 0.0 {
            self.throughput_per_second =
                successful_samples.len() as f32 / self.total_duration.as_secs_f32();
        }
    }

    pub fn print_summary(&self) {
        println!("Load Test Results for {}:", self.test_name);
        println!("  Total samples: {}", self.samples.len());
        println!("  Success rate: {:.2}%", self.success_rate * 100.0);
        println!("  Average response time: {:?}", self.average_response_time);
        println!("  Throughput: {:.2} ops/sec ", self.throughput_per_second);
        println!("  Test duration: {:?}", self.total_duration);
    }
}

// Performance Testing Framework
//
// Canonical performance testing utilities for the Songbird ecosystem.

use songbird_types::{errors::SongbirdResult, SongbirdError};
use std::collections::HashMap;
use std::sync::Arc;
use std::time::{Duration, Instant};
use tokio::sync::RwLock;

/// Performance testing framework for canonical performance validation
#[derive(Debug)]
pub struct PerformanceTestFramework {
    /// Benchmark results
    results: Arc<RwLock<HashMap<String, BenchmarkResult>>>,
    /// Test configuration
    config: PerformanceTestConfig,
}

/// Performance test configuration
#[derive(Debug, Clone)]
pub struct PerformanceTestConfig {
    /// Test timeout
    pub timeout: Duration,
    /// Number of iterations
    pub iterations: usize,
    /// Warmup iterations
    pub warmup_iterations: usize,
    /// Target throughput (operations per second)
    pub target_throughput: f64,
}

/// Benchmark result
#[derive(Debug, Clone)]
pub struct BenchmarkResult {
    /// Test name
    pub name: String,
    /// Average duration
    pub avg_duration: Duration,
    /// Minimum duration
    pub min_duration: Duration,
    /// Maximum duration
    pub max_duration: Duration,
    /// Throughput (operations per second)
    pub throughput: f64,
    /// Success rate
    pub success_rate: f64,
}

impl PerformanceTestFramework {
    /// Create a new performance testing framework
    #[must_use]
    pub fn new() -> Self {
        Self {
            results: Arc::new(RwLock::new(HashMap::new())),
            config: PerformanceTestConfig::default(),
        }
    }

    /// Run a performance benchmark
    ///
    /// # Errors
    /// Returns an error if the benchmark fails.
    pub async fn run_benchmark<F, Fut, T>(
        &self,
        name: &str,
        operation: F,
    ) -> SongbirdResult<BenchmarkResult>
    where
        F: Fn() -> Fut + Clone,
        Fut: std::future::Future<Output = SongbirdResult<T>>,
    {
        let mut durations = Vec::new();
        let mut successes = 0;

        // Warmup iterations
        for _ in 0..self.config.warmup_iterations {
            let _ = operation().await;
        }

        // Actual benchmark iterations
        for _ in 0..self.config.iterations {
            let start = Instant::now();
            match operation().await {
                Ok(_) => {
                    successes += 1;
                    durations.push(start.elapsed());
                }
                Err(_) => {
                    durations.push(start.elapsed());
                }
            }
        }

        if durations.is_empty() {
            return Err(SongbirdError::service("test-utils", "No benchmark data collected"));
        }

        let total_duration: Duration = durations.iter().sum();
        let avg_duration = total_duration / durations.len() as u32;
        let min_duration = *durations.iter().min().ok_or_else(|| SongbirdError::Configuration {
            message: "No durations recorded for performance test".to_string(),
            field: Some("performance_test".to_string()),
            suggestion: Some("Ensure iterations > 0".to_string()),
        })?;
        let max_duration = *durations.iter().max().ok_or_else(|| SongbirdError::Configuration {
            message: "No durations recorded for performance test".to_string(),
            field: Some("performance_test".to_string()),
            suggestion: Some("Ensure iterations > 0".to_string()),
        })?;
        let throughput = self.config.iterations as f64 / total_duration.as_secs_f64();
        let success_rate = f64::from(successes) / self.config.iterations as f64;

        let result = BenchmarkResult {
            name: name.to_string(),
            avg_duration,
            min_duration,
            max_duration,
            throughput,
            success_rate,
        };

        let mut results = self.results.write().await;
        results.insert(name.to_string(), result.clone());

        Ok(result)
    }

    /// Store a benchmark result
    pub async fn store_result(&self, name: String, result: BenchmarkResult) {
        let mut results = self.results.write().await;
        results.insert(name, result);
    }

    /// Get benchmark results as a reference to avoid cloning the entire `HashMap`
    pub async fn get_results_ref(
        &self,
    ) -> tokio::sync::RwLockReadGuard<'_, HashMap<String, BenchmarkResult>> {
        self.results.read().await
    }

    /// Get benchmark results (only clone when explicitly needed)
    pub async fn get_results_cloned(&self) -> SongbirdResult<HashMap<String, BenchmarkResult>> {
        let results = self.results.read().await;
        Ok(results.clone())
    }

    /// Assert performance meets requirements
    ///
    /// # Errors
    /// Returns an error if performance requirements are not met.
    pub async fn assert_performance_requirements(
        &self,
        benchmark_name: &str,
    ) -> SongbirdResult<()> {
        let results = self.results.read().await;
        let result = results.get(benchmark_name).ok_or_else(|| {
            SongbirdError::service(
                "test-utils",
                format!("Benchmark '{}' not found", benchmark_name),
            )
        })?;

        if result.throughput < self.config.target_throughput {
            return Err(SongbirdError::service(
                "test-utils",
                format!(
                    "Throughput {} below target {}",
                    result.throughput, self.config.target_throughput
                ),
            ));
        }

        if result.success_rate < 0.95 {
            return Err(SongbirdError::service(
                "test-utils",
                format!("Success rate {} below 95%", result.success_rate),
            ));
        }

        Ok(())
    }
}

impl Default for PerformanceTestFramework {
    fn default() -> Self {
        Self::new()
    }
}

impl Default for PerformanceTestConfig {
    fn default() -> Self {
        Self {
            timeout: Duration::from_secs(60),
            iterations: 1000,
            warmup_iterations: 100,
            target_throughput: 100.0, // 100 ops/sec default
        }
    }
}

