impl CanonicalProtocolRouter {
    /// Create a new protocol router
    pub fn new() -> Self {
        Self {
            handlers: HashMap::new(),
            default_protocol: "http".to_string(),
        }
    }

    /// Register a protocol handler
    pub fn register_handler(&mut self, handler: Arc<dyn CanonicalProtocolHandler>) {
        self.handlers.insert(handler.protocol_name().to_string(), handler);
    }

    /// Route request to appropriate protocol handler
    ///
    /// # Errors
    ///
    /// Returns an error if:
    /// - The requested protocol is not supported
    /// - The protocol handler fails to process the request
    pub async fn route_request(
        &self,
        service: &CanonicalServiceInfo,
        request: &CanonicalAdapterRequest,
    ) -> SongbirdResult<CanonicalAdapterResponse> {
        // Determine protocol from service endpoints
        let protocol = service
            .endpoints
            .first()
            .map(|e| e.protocol.clone())
            .unwrap_or_else(|| self.default_protocol.clone());

        // Get appropriate handler
        let handler = self.handlers.get(&protocol).ok_or_else(|| SongbirdError::Service {
            service: format!("protocol:{}", protocol),
            message: format!("Protocol '{}' is not supported", protocol),
            suggested_alternatives: self.handlers.keys().cloned().collect(),
            recovery_actions: vec![],
        })?;

        // Handle request
        handler.handle_request(service, request).await
    }
}

