    Unhealthy,
    /// Health status is unknown
    Unknown,
}

impl Default for UnifiedHealthStatus {


    fn default() -> Self {
        Self::Unknown


}
}

impl fmt::Display for UnifiedHealthStatus {

fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result  {let status_str = match self {
