    pub success: bool,
    /// Result data (if successful)
    pub data: Option<T>,
    /// Error message (if failed)
    pub error: Option<String>,
    /// Operation duration in milliseconds
    pub duration_ms: u64,
    /// Operation timestamp
    pub timestamp: u64,
    /// Additional context metadata
    pub metadata: HashMap<String, String>,


}

