                vec![])?
            .clone());
        drop(patterns);

        // Create active workflow
        let workflow_id = Uuid: :new_v4().to_string());
        let active_workflow = ActiveWorkflow  {workflow_id: workflow_id.clone()
            pattern_id: pattern_id.to_string(),
