    Ok(())
}

fn clean_directory(dir: &str, patterns: &[&str]) -> Result<(), Box<dyn std::error::Error>> {
    for entry in WalkDir::new(dir).into_iter().filter_map(|e| e.ok()) {
        let path = entry.path();
        if path.extension().and_then(|s| s.to_str()) == Some("rs") {
            clean_file(path, patterns)?;
        }
    }
    Ok(())
}

fn clean_file(path: &Path, patterns: &[&str]) -> Result<(), Box<dyn std::error::Error>> {
    let content = fs::read_to_string(path)?;
    let mut cleaned_content = content.clone();
    let mut changes_made = false;

    for pattern in patterns {
        let regex = Regex::new(pattern)?;
        if regex.is_match(&cleaned_content) {
            cleaned_content = regex.replace_all(&cleaned_content, "").to_string();
            changes_made = true;
        }
    }

    if changes_made {
        println!("  🧹 Cleaned: {}", path.display());
        fs::write(path, cleaned_content)?;
    }

    Ok(())
}

#!/usr/bin/env rust-script

//! Modernize Response Patterns to Canonical Types
//!
//! This script fixes the inconsistent response patterns throughout the codebase
//! to use the canonical types properly.

use std::fs;
use std::path::Path;
use walkdir::WalkDir;

fn main() -> Result<(), Box<dyn std::error::Error>> {
    println!("🔧 Modernizing response patterns to canonical types...");

    let crates_dir = Path::new("crates");

    for entry in WalkDir::new(crates_dir) {
        let entry = entry?;
        if entry.file_type().is_file() && entry.path().extension() == Some("rs".as_ref()) {
            modernize_file(entry.path())?;
        }
    }

    println!("✅ Response pattern modernization complete!");
    Ok(())
}

fn modernize_file(path: &Path) -> Result<(), Box<dyn std::error::Error>> {
    let content = fs::read_to_string(path)?;
    let mut updated_content = content.clone();

    // Pattern 1: Functions returning Result<(), SongbirdError> should just return Ok(())
    // not Ok(SongbirdResponse::success(()))
    let pattern1 = r"Ok\(SongbirdResponse::success\(\(\)\)\)";
    let replacement1 = "Ok(())";
    updated_content = regex::Regex::new(pattern1)?.replace_all(&updated_content, replacement1).to_string();

    // Pattern 2: Fix function signatures that should return Result<(), SongbirdError>
    // instead of SongbirdResult<()>
    let pattern2 = r"-> SongbirdResult<\(\)>";
    let replacement2 = "-> Result<()>";
    updated_content = regex::Regex::new(pattern2)?.replace_all(&updated_content, replacement2).to_string();

    // Pattern 3: Import the correct Result type
    if updated_content.contains("use songbird_errors::") && !updated_content.contains("use songbird_errors::Result") {
        let pattern3 = r"use songbird_errors::\{([^}]*)\}";
        if let Some(captures) = regex::Regex::new(pattern3)?.captures(&updated_content) {
            let imports = &captures[1];
            if !imports.contains("Result") {
                let new_imports = format!("{}, Result", imports);
                updated_content = updated_content.replace(&captures[0], &format!("use songbird_errors::{{{}}}", new_imports));
            }
        }
    }

    if content != updated_content {
        fs::write(path, updated_content)?;
        println!("📝 Updated: {}", path.display());
    }

    Ok(())
}

#!/usr/bin/env rust-script

//! # Panic Pattern Replacer
//! 
//! This script systematically replaces panic-prone patterns with proper error handling
//! throughout the Songbird codebase.

use std::fs;
use std::path::Path;
use regex::Regex;

fn main() -> Result<(), Box<dyn std::error::Error>> {
    println!("🔧 Starting panic pattern replacement...");

    let patterns = vec![
        // .unwrap() patterns
        PanicPattern {
            pattern: Regex::new(r"\.unwrap\(\)")?,
            replacement: ".map_err(|e| SongbirdError::internal(format!(\"Operation failed: {:?}\", e)))?",
            description: "Replace .unwrap() with proper error handling",
        },

        // .expect() patterns with generic messages
        PanicPattern {
            pattern: Regex::new(r"\.expect\(\"([^\"]+)\"\)")?,
            replacement: ".map_err(|e| SongbirdError::internal(format!(\"$1: {:?}\", e)))?",
            description: "Replace .expect() with proper error handling",
        },

        // panic! patterns
        PanicPattern {
            pattern: Regex::new(r"panic!\(\"([^\"]+)\"\)")?,
            replacement: "return Err(SongbirdError::internal(\"$1\"))",
            description: "Replace panic! with proper error return",
        },

        // unwrap_or_else patterns that might panic
        PanicPattern {
            pattern: Regex::new(r"\.unwrap_or_else\(\|\| panic!\(\"([^\"]+)\"\)\)")?,
            replacement: ".map_err(|e| SongbirdError::internal(format!(\"$1: {:?}\", e)))?",
            description: "Replace unwrap_or_else panic with proper error handling",
        },
    ];

    let target_dirs = vec![
        "crates/songbird-types/src",
        "crates/songbird-network/src", 
        "crates/songbird-universal/src",
        "crates/songbird-core/src",
        "crates/songbird-config/src",
    ];

    for dir in target_dirs {
        if Path::new(dir).exists() {
            process_directory(dir, &patterns)?;
        } else {
            println!("⚠️  Directory not found: {}", dir);
        }
    }

    println!("✅ Panic pattern replacement complete!");
    Ok(())
}

struct PanicPattern {
    pattern: Regex,
    replacement: &'static str,
    description: &'static str,
}

fn process_directory(dir: &str, patterns: &[PanicPattern]) -> Result<(), Box<dyn std::error::Error>> {
    println!("📁 Processing directory: {}", dir);

    for entry in fs::read_dir(dir)? {
        let entry = entry?;
        let path = entry.path();

        if path.is_dir() {
            // Recursively process subdirectories
            if let Some(path_str) = path.to_str() {
                process_directory(path_str, patterns)?;
            }
        } else if path.extension().map_or(false, |ext| ext == "rs") {
            // Process Rust files
            if let Some(path_str) = path.to_str() {
                process_file(path_str, patterns)?;
            }
        }
    }

    Ok(())
}

fn process_file(file_path: &str, patterns: &[PanicPattern]) -> Result<(), Box<dyn std::error::Error>> {
    let content = fs::read_to_string(file_path)?;
    let mut modified_content = content.clone();
    let mut changes_made = false;

    for pattern in patterns {
        if pattern.pattern.is_match(&modified_content) {
            println!("🔧 Applying pattern '{}' to: {}", pattern.description, file_path);
            modified_content = pattern.pattern.replace_all(&modified_content, pattern.replacement).to_string();
            changes_made = true;
        }
    }

    if changes_made {
        // Add necessary imports if not present
        if !modified_content.contains("use songbird_errors::SongbirdError;") && 
           !modified_content.contains("use songbird_types::SongbirdError;") {
            // Find the appropriate place to add the import
            if let Some(use_pos) = modified_content.find("use ") {
                let import = "use songbird_errors::SongbirdError;\n";
                modified_content.insert_str(use_pos, import);
            }
        }

        fs::write(file_path, modified_content)?;
        println!("✅ Updated: {}", file_path);
    }

    Ok(())
}

