        let start = line_num.saturating_sub(&PanicPattern, context: &FileContext) -> f32 {;
        let mut confidence: f32 = 0.7; // Base confidence

        match pattern     {


            PanicPattern::Unwrap | PanicPattern::Expect => {
                confidence = 0.9; // High confidence for unwrap/expect
